  return <>
    <button type="button" tabIndex={-1} aria-hidden="true" data-testid="conversations-backdrop" onClick={onClose} className={cn('z-20 hidden cursor-default sm:block', placement === 'above' ? 'fixed inset-0' : 'absolute inset-0')} />
    <section role="dialog" aria-label={labels.historyDialog} data-testid="conversations"
      className={cn('fixed inset-0 z-50 flex flex-col bg-background text-foreground sm:absolute sm:inset-auto sm:z-30 sm:w-[23rem] sm:rounded-2xl sm:border sm:border-border sm:shadow-lg',
        placement === 'above' ? 'sm:bottom-full sm:left-0 sm:mb-2 sm:max-h-[min(26rem,60dvh)]' : 'sm:top-12 sm:right-3 sm:max-h-[min(34rem,calc(100%-4rem))]')}>
      <header className="flex shrink-0 items-center gap-2 border-b border-border px-3 py-2.5 max-sm:pt-[max(0.625rem,env(safe-area-inset-top))]">
        <Button size="icon-sm" variant="ghost" aria-label={labels.closeHistory} title={labels.close} data-testid="conversations-close" onClick={onClose} className="sm:hidden"><ArrowLeftIcon className="size-4" aria-hidden="true" /></Button>
        <h3 className="m-0 min-w-0 flex-1 font-(family-name:--chat-display) text-sm font-semibold tracking-tight">{labels.history}</h3>
        {conversations.onNew && <Button size="sm" variant="outline" data-testid="conversation-new" onClick={() => { conversations.onNew!(); onClose(); }}><icons.newChat className="size-3.5" aria-hidden="true" />{labels.newConversation}</Button>}
        <Button size="icon-sm" variant="ghost" aria-label={labels.closeHistory} title={labels.close} onClick={onClose} className="max-sm:hidden"><XIcon className="size-4" aria-hidden="true" /></Button>
      </header>
      <ConversationList conversations={conversations} onPicked={onClose} autoFocus />
      {onBrowseEarlier && <footer className="shrink-0 border-t border-border p-1.5 max-sm:pb-[max(0.375rem,env(safe-area-inset-bottom))]">
        <Button size="sm" variant="ghost" data-testid="history-earlier" className="w-full justify-start text-muted-foreground" onClick={() => { onBrowseEarlier(); onClose(); }}>
          <icons.history className="size-3.5" aria-hidden="true" />{labels.earlierInConversation}</Button>
      </footer>}
    </section>
  </>;
}

function line(message: Message, developer: boolean, labels: ChatLabels): { readonly role: string; readonly body: string; readonly assistant?: AssistantMessage } | undefined {
  if (message.role === 'system') return developer ? { role: labels.roleSystem, body: typeof message.content === 'string' ? message.content : message.content.map(part => part.text).join('\n') } : undefined;
  if (message.role === 'toolResult') return { role: labels.roleToolResult(message.toolName, message.isError), body: message.content.map(part => part.type === 'text' ? part.text : '[image result]').join('\n') };
  if (message.role === 'user') return { role: labels.roleUser, body: typeof message.content === 'string' ? message.content : message.content.filter(part => part.type !== 'text' || !isFileBlock(part.text)).map(part => part.type === 'text' ? part.text : '[image attachment]').join('\n') };
  const body = message.content.map(part => part.type === 'text' ? part.text : part.type === 'toolCall' ? `[tool call: ${part.name}]` : developer ? `[reasoning]\n${part.thinking}` : '').filter(Boolean).join('\n\n');
  return { role: labels.roleAssistant(message.stopReason === 'aborted' ? 'interrupted' : message.stopReason === 'error' ? 'failed' : 'ok'), body, ...(message.stopReason === 'error' || message.stopReason === 'aborted' ? {} : { assistant: message }) };
}

type HistoryRow = { readonly key: string; readonly role: string; readonly body: string; readonly entryId: string; readonly assistant: AssistantMessage | undefined };
const replyText = (message: AssistantMessage) => message.content.flatMap(part => part.type === 'text' && part.text ? [part.text] : []).join('\n\n');

/** Read-only older records of the open conversation, paged in by the controller. Historical tool results are not current actions. */
export function HistoryPanel({ history, developer, connected, onLoad, onClose, replyFooter }: {
  readonly history: ChatHistoryState; readonly developer: boolean; readonly connected: boolean; readonly onLoad: () => void; readonly onClose: () => void;
  /** The host's reply footer, shown under each earlier reply that has text. Earlier records get no actions. */
  readonly replyFooter?: ((reply: ReplyRef) => ReactNode) | undefined;
}) {
  const { labels, icons } = useChatText();
  const entries: readonly EntryRecord[] = 'entries' in history ? history.entries : [];
  const rows = entries.flatMap((entry): HistoryRow[] => entry.model?.length
    ? entry.model.flatMap((message, index) => { const made = line(message, developer, labels); return made ? [{ key: `history:${entry.id}:${index}`, entryId: String(entry.id), assistant: undefined, ...made }] : []; })
    : [{ key: `history:${entry.id}`, role: labels.roleEvent, body: entry.head === undefined ? entry.kind : labels.contextBoundary, entryId: String(entry.id), assistant: undefined }]);
  const exhausted = history.kind === 'ready' && !history.hasMore;
  return <section aria-label={labels.earlierMessages} data-testid="history" aria-live="off" className="shrink-0 border-b border-border bg-muted/20">
    <div className="mx-auto flex max-w-3xl items-center gap-2 px-4 py-2">
      <icons.history className="size-4 text-muted-foreground" aria-hidden="true" />
      <h3 className="m-0 min-w-0 flex-1 truncate font-(family-name:--chat-display) text-sm font-medium">{labels.earlierMessages} <span className="font-normal text-muted-foreground">{labels.readOnly}</span></h3>
      <Button size="sm" variant="outline" data-testid="history-load" onClick={onLoad} disabled={!connected || history.kind === 'loading' || history.kind === 'disabled' || exhausted}>
        {history.kind === 'error' ? labels.retry : history.kind === 'loading' ? labels.loadingShort : labels.loadEarlier}</Button>
      <Button size="icon-sm" aria-label={labels.returnToConversation} title={labels.returnToConversation} onClick={onClose}><XIcon className="size-4" aria-hidden="true" /></Button>
    </div>
    <div className="mx-auto max-h-[40dvh] max-w-3xl space-y-3 overflow-y-auto px-4 pb-3">
      {history.kind === 'error' && <p role="alert" className="m-0 text-sm text-destructive">{labels.historyFailed}</p>}
      {history.kind === 'idle' && <p className="m-0 text-sm text-muted-foreground">{labels.loadPage}</p>}
      {rows.map(row => <article key={row.key} data-history-row-id={row.key} className="rounded-lg border border-border bg-background/60 px-3 py-2">
        <p className="m-0 mb-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">{row.role}</p>
        <div className="text-sm opacity-90"><Markdown text={row.body} /></div>
        {replyFooter && row.assistant && replyText(row.assistant) && replyFooter({ key: row.key, text: replyText(row.assistant), entryId: row.entryId, ...replyMeta(row.assistant) })}</article>)}
      {history.kind === 'ready' && !rows.length && <p className="m-0 text-sm text-muted-foreground">{labels.noRecords}</p>}
      {exhausted && <p className="m-0 text-center text-xs text-muted-foreground">{labels.beginning}</p>}
    </div>
  </section>;
}

'use client';

import { createElement, Fragment, memo, useMemo } from 'react';
import type { ReactNode } from 'react';
import { Marked } from 'marked';
import { decodeHTML } from 'entities';
import { CodeBlock } from './code-block';
import { useChatText } from './labels';
import type { ChatLabels } from './labels';

/*
 * Safe Markdown for model output. Tokens are mapped to React elements one by one: raw HTML is shown as text, images are
 * shown as their alt text (nothing is fetched), and a link is only rendered when it is a plain http(s) URL.
 * Ported from the v4 `@hachej/boring-ui-kit` chat markdown renderer; the styling is Tailwind and fenced code gets a code block card.
 */
export interface CommandMention { readonly name: string; readonly behavior: 'execute' | 'insert' }
export interface CommandMentions {
  readonly commands: readonly CommandMention[];
  readonly onActivate: (command: CommandMention) => void;
}

const markdown = new Marked({ gfm: true, breaks: false, pedantic: false });

function isRecord(value: unknown): value is Record<string, unknown> { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function text(value: unknown): string { return typeof value === 'string' ? value : ''; }
function visible(value: unknown): string {
  if (!isRecord(value)) return '';
  if (value['type'] === 'br') return '\n';
  if (Array.isArray(value['tokens'])) return value['tokens'].map(visible).join('');
  const content = text(value['text']);
  return value['type'] === 'text' && value['escaped'] !== true ? decodeHTML(content) : content;
}
function containsHtml(value: unknown): boolean {
  if (!isRecord(value)) return false;
  return value['type'] === 'html' || Array.isArray(value['tokens']) && value['tokens'].some(containsHtml);
}
function literal(value: string): ReactNode { return <span className="whitespace-pre-wrap">{value}</span>; }

interface Context { readonly mentions: CommandMentions | undefined; readonly onCopy: ((text: string) => Promise<void>) | undefined; readonly labels: ChatLabels }

function children(value: unknown, context: Context, before = '', after = '', inline = false): ReactNode {
  if (!Array.isArray(value)) return null;
  if (!context.mentions) return value.map((token: unknown, index) => <Fragment key={index}>{renderToken(token, context)}</Fragment>);
  const shown = value.map(visible), source = before + shown.join('') + after;
  const active = inline && value.some(containsHtml) ? { ...context, mentions: undefined } : context;
  let position = before.length;
  return value.map((token: unknown, index) => {
    const start = position;
    position += shown[index]?.length ?? 0;
    return <Fragment key={index}>{renderToken(token, active, source.slice(0, start), source.slice(position))}</Fragment>;
  });
}

const mentionPattern = /(^|[\s(\[{"'“‘])\/([A-Za-z0-9_][A-Za-z0-9_-]*)(?=$|\s|[.,;!?)}\]"'”’]+(?=$|\s))/g;
function mentionText(value: string, mentions: CommandMentions | undefined, before: string, after: string, labels: ChatLabels): ReactNode {
  if (!mentions?.commands.length || !value.includes('/')) return value;
  const commands = new Map(mentions.commands.filter(item => /^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(item.name)
    && (item.behavior === 'execute' || item.behavior === 'insert')).map(item => [item.name, item]));
  if (!commands.size) return value;
  const source = before + value + after, start = before.length, end = start + value.length;
  const pieces: ReactNode[] = [];
  let cursor = 0;
  for (const match of source.matchAll(mentionPattern)) {
    if (match.index === undefined) continue;
    const boundary = match[1] ?? '', name = match[2];
    if (!name) continue;
    const offset = match.index + boundary.length, limit = offset + name.length + 1;
    const command: CommandMention | undefined = commands.get(name);
    if (!command || offset < start || limit > end || offset - start < cursor) continue;
    const selected = { name: command.name, behavior: command.behavior };
    const at = offset - start;
    if (at > cursor) pieces.push(value.slice(cursor, at));
    pieces.push(<button key={at} type="button" data-testid="command-mention" aria-label={labels.runCommand(selected.name, selected.behavior === 'execute')}
      className="cursor-pointer rounded bg-muted px-1 font-mono text-[0.92em] text-foreground hover:bg-accent" onClick={() => mentions.onActivate(selected)}>/{selected.name}</button>);
    cursor = limit - start;
  }
  if (!pieces.length) return value;
  if (cursor < value.length) pieces.push(value.slice(cursor));
  return pieces;
}

function linkTarget(value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined;
  const decoded = decodeHTML(value);
  if (!/^https?:\/\//i.test(decoded) || /[\u0000- \u007f-\u009f\\]/.test(decoded)) return undefined;
  const authority = /^https?:\/\/([^/?#]*)/i.exec(decoded)?.[1];
  if (!authority || authority.includes('@')) return undefined;
  try {
    const url = new URL(decoded);
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) return undefined;
    return url.href;
  } catch { return undefined; }
}

function cells(value: unknown, header: boolean, context: Context): ReactNode {
  if (!Array.isArray(value)) return null;
  return value.map((cell: unknown, index) => {
    if (!isRecord(cell)) return null;
    const alignment = cell['align'];
    const textAlign = alignment === 'left' || alignment === 'center' || alignment === 'right' ? alignment : undefined;
    return createElement(header ? 'th' : 'td', { key: index, style: { textAlign }, className: header ? 'px-3 py-1.5 font-semibold' : 'px-3 py-1.5', ...(header ? { scope: 'col' } : {}) },
      children(cell['tokens'], context, '', '', true));
  });
}

const HEADINGS: Record<number, string> = {
  1: 'mt-6 mb-2 text-xl font-semibold tracking-tight', 2: 'mt-5 mb-2 text-base font-semibold tracking-tight', 3: 'mt-4 mb-1.5 text-sm font-semibold',
  4: 'mt-4 mb-1 text-sm font-semibold', 5: 'mt-3 mb-1 text-sm font-medium', 6: 'mt-3 mb-1 text-sm font-medium text-muted-foreground',
};

// Marked's extension token includes arbitrary fields. Narrow those fields here before creating React nodes.
function renderToken(value: unknown, context: Context, before = '', after = ''): ReactNode {
  if (!isRecord(value)) return null;
  const raw = text(value['raw']), content = text(value['text']), mentions = context.mentions;
  switch (value['type']) {
    case 'space': case 'def': return null;
    case 'paragraph': return <p className="my-3 first:mt-0 last:mb-0">{children(value['tokens'], context, '', '', true)}</p>;
    case 'heading': {
      const depth = value['depth'];
      return typeof depth === 'number' && Number.isInteger(depth) && depth >= 1 && depth <= 6
        ? createElement(`h${depth}`, { className: `${HEADINGS[depth]} first:mt-0` }, children(value['tokens'], context, '', '', true)) : literal(raw);
    }
    case 'text': return Array.isArray(value['tokens']) ? children(value['tokens'], context, before, after, true)
      : value['escaped'] === true ? literal(content) : mentionText(decodeHTML(content), mentions, before, after, context.labels);
    case 'escape': return content;
    case 'strong': return <strong className="font-semibold text-foreground">{children(value['tokens'], context, before, after, true)}</strong>;
    case 'em': return <em>{children(value['tokens'], context, before, after, true)}</em>;
    case 'del': return <del className="text-muted-foreground">{children(value['tokens'], context, before, after, true)}</del>;
    case 'blockquote': return <blockquote className="my-3 rounded-lg border border-border bg-muted/40 px-4 py-2 text-muted-foreground [&_p]:my-1">{children(value['tokens'], context)}</blockquote>;
    case 'br': return <br />;
    case 'hr': return <hr className="my-5 border-border" />;
    case 'codespan': return <code className="rounded-md bg-muted px-1.5 py-0.5 font-mono text-[0.85em] whitespace-pre-wrap">{content}</code>;
    case 'code': return <CodeBlock code={content} {...(typeof value['lang'] === 'string' && value['lang'] ? { language: value['lang'] } : {})} {...(context.onCopy ? { onCopy: context.onCopy } : {})} />;
    case 'html': return value['block'] === true ? <pre className="my-3 overflow-x-auto rounded-lg bg-muted/50 p-3 font-mono text-xs whitespace-pre-wrap">{raw}</pre> : literal(raw);
    case 'image': return literal(decodeHTML(content) || raw);
    case 'link': {
      const href = linkTarget(value['href']), title = typeof value['title'] === 'string' ? decodeHTML(value['title']) : undefined;
      return href ? <a href={href} title={title} target="_blank" rel="noopener noreferrer"
        className="font-medium text-foreground underline decoration-muted-foreground/50 underline-offset-4 hover:decoration-foreground">{children(value['tokens'], context)}</a> : children(value['tokens'], context);
    }
    case 'list': {
      const start = value['start'];
      return value['ordered'] === true
        ? <ol start={typeof start === 'number' && Number.isSafeInteger(start) ? start : undefined} className="my-3 list-decimal ps-6 marker:text-muted-foreground">{children(value['items'], context)}</ol>
        : <ul className="my-3 list-disc ps-6 marker:text-muted-foreground">{children(value['items'], context)}</ul>;
    }
    case 'list_item': return <li className="ps-1 [&+li]:mt-1 [&>p]:my-1 [&>ol]:my-1 [&>ul]:my-1">{children(value['tokens'], context, '', '', true)}</li>;
    case 'checkbox': return <input type="checkbox" checked={value['checked'] === true} disabled readOnly aria-label={context.labels.taskStatus} className="me-1.5 align-middle accent-foreground" />;
    case 'table': return <div className="my-3 overflow-x-auto rounded-lg border border-border"><table className="w-full border-collapse text-left tabular-nums">
      <thead className="bg-muted/50">{<tr>{cells(value['header'], true, context)}</tr>}</thead>
      <tbody className="[&_tr]:border-t [&_tr]:border-border">{Array.isArray(value['rows']) ? value['rows'].map((row: unknown, index) => <tr key={index}>{cells(row, false, context)}</tr>) : null}</tbody></table></div>;
    default: return literal(raw);
  }
}

/** One top-level block; unchanged blocks skip re-rendering while a long answer streams. */
const Block = memo(function Block({ token, context }: { readonly token: unknown; readonly context: Context }) {
  return <>{renderToken(token, context)}</>;
}, (a, b) => isRecord(a.token) && isRecord(b.token) && a.token['raw'] === b.token['raw'] && a.token['type'] === b.token['type'] && a.context.mentions === b.context.mentions && a.context.onCopy === b.context.onCopy && a.context.labels === b.context.labels);

export const Markdown = memo(function Markdown({ text: source, commandMentions, onCopy, streaming = false }: {
  readonly text: string; readonly commandMentions?: CommandMentions; readonly onCopy?: (text: string) => Promise<void>; readonly streaming?: boolean;
}) {
  const tokens = useMemo(() => { try { return markdown.lexer(source); } catch { return null; } }, [source]);
  const mentions = source.includes('/') && commandMentions?.commands.length ? commandMentions : undefined;
  const { labels } = useChatText();
  const context = useMemo<Context>(() => ({ mentions, onCopy, labels }), [mentions, onCopy, labels]);
  const body = useMemo(() => {
    if (!tokens) return literal(source);
    // With mentions enabled, positions are relative to the whole text, so render the token list as one unit.
    if (mentions) return children(tokens, context);
    return tokens.map((token, index) => <Block key={index} token={token} context={context} />);
  }, [tokens, source, mentions, context]);
  return <div data-testid="message-text" data-streaming={streaming ? 'true' : undefined} className="min-w-0 text-sm leading-relaxed [overflow-wrap:anywhere]">
    {body}
  </div>;
});

'use client';

import { useEffect, useRef, useState } from 'react';
import { FileTextIcon, FolderIcon } from 'lucide-react';
import { usePickerKeyboard } from './picker-keyboard';
import type { MentionResult, MentionsConfig } from './config';
import { cn } from '../utils/utils';
import { useChatText } from './labels';

function highlight(text: string, query: string) {
  const at = query ? text.toLowerCase().indexOf(query.toLowerCase()) : -1;
  if (at < 0) return <>{text}</>;
  return <>{text.slice(0, at)}<mark className="bg-transparent font-semibold text-foreground underline decoration-ring/60 underline-offset-2">{text.slice(at, at + query.length)}</mark>{text.slice(at + query.length)}</>;
}

/** The `@` file picker, ported from v2's `MentionPicker`: debounced search, one highlighted row, name over path. */
export function MentionMenu({ query, search, generation, onSelect, onDismiss }: {
  readonly query: string;
  readonly generation?: MentionsConfig['generation'];
  readonly search: MentionsConfig['search'];
  readonly onSelect: (path: string) => void;
  readonly onDismiss: () => void;
}) {
  const { labels } = useChatText();
  // Results are tagged with the search function that produced them: a binding switch hides the previous binding's rows at once.
  const [outcome, setOutcome] = useState<{ readonly search: MentionsConfig['search']; readonly results: readonly MentionResult[]; readonly failure: string | null }>();
  const shown = outcome?.search === search ? outcome : undefined;
  const results = shown?.results ?? [];
  const failure = shown?.failure ?? null;
  const [active, setActive] = useState(0);
  const list = useRef<HTMLUListElement>(null), container = useRef<HTMLDivElement>(null);
  const searcher = useRef(search); searcher.current = search;
  useEffect(() => {
    setActive(0);
    const abort = new AbortController();
    const timer = setTimeout(() => {
      searcher.current(query, abort.signal).then(found => { if (!abort.signal.aborted) setOutcome({ search, results: found.slice(0, 8), failure: null }); },
        cause => { if (!abort.signal.aborted) setOutcome({ search, results: [], failure: cause instanceof Error ? cause.message : labels.searchFailed }); });
    }, 120);
    return () => { clearTimeout(timer); abort.abort(); };
  }, [query, search, generation]);
  useEffect(() => {
    const outside = (event: MouseEvent) => { if (container.current && !container.current.contains(event.target as Node)) onDismiss(); };
    document.addEventListener('mousedown', outside);
    return () => document.removeEventListener('mousedown', outside);
  }, [onDismiss]);
  usePickerKeyboard({ count: results.length, activeIdx: active, setActiveIdx: setActive, listRef: list, onSelect: index => { const item = results[index]; if (item) onSelect(item.path); }, onDismiss });

  if (results.length === 0 && !failure) return null;
  return <div ref={container} data-testid="mention-menu" className="absolute inset-x-0 bottom-full z-20 mb-2 overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground shadow-lg">
    {failure ? <div role="alert" data-testid="mention-error" className="px-3 py-2 text-xs text-destructive">{failure}</div>
      : <ul ref={list} role="listbox" aria-label={labels.workspaceFiles} className="m-0 max-h-[min(14rem,40dvh)] list-none overflow-y-auto p-0 py-1">
        {results.map((item, index) => {
          const name = item.path.split('/').pop() ?? item.path;
          const Icon = item.kind === 'directory' ? FolderIcon : FileTextIcon;
          return <li key={item.path} role="option" aria-selected={index === active} data-testid="mention-item" data-path={item.path} title={item.path}
            onMouseEnter={() => setActive(index)} onMouseDown={event => { event.preventDefault(); onSelect(item.path); }}
            className={cn('flex cursor-pointer items-center gap-2.5 px-3 py-1.5 text-xs max-sm:min-h-11 pointer-coarse:min-h-11', index === active ? 'bg-accent text-foreground' : 'text-muted-foreground')}>
            <Icon className="size-3.5 shrink-0 opacity-70" aria-hidden="true" />
            <span className="flex min-w-0 flex-col gap-0.5"><span className="truncate font-medium text-foreground">{highlight(name, query)}</span>
              <span className="truncate text-xs opacity-70">{item.path}</span></span>
          </li>;
        })}
      </ul>}
  </div>;
}

'use client';

import { useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import type { ImageContent, ToolResultMessage, UserMessage } from '@earendil-works/pi-ai';
import { AlertCircleIcon, CircleSlashIcon, FileIcon, FileSpreadsheetIcon, FileTextIcon, ImageIcon, PresentationIcon } from 'lucide-react';
import { CopyButton } from './code-block';
import { Markdown } from './markdown';
import type { CommandMentions } from './markdown';
import { ArtifactCard } from './artifact-card';
import type { ArtifactsConfig } from './artifact';
import { ApprovalCard } from './approval-card';
import { QuestionCard } from './question-card';
import type { AnswerOutcome } from './question-card';
import { ActivityBlock } from './activity';
import type { ActivityState } from './activity';
import { Shimmer } from './shimmer';
import { ToolCard } from './tool';
import { thumbnail } from './composer';
import { displayName, fileKind, isUploadPath, pieces, visibleParts } from './config';
import type { FileKind, Piece, PreviewRead } from './config';
import { isFileBlock, segments } from './rows';
import type { DeriveOptions, Row } from './rows';
import { Button } from '../button/button';
import { BlockActions } from '../button/actions';
import type { BlockAction } from '../button/actions';
import { useChatText } from './labels';
import type { ReplyRef } from './config';
import { cn } from '../utils/utils';

export interface RowContext {
  readonly developer: boolean;
  readonly groupTool: DeriveOptions['groupTool'];
  readonly commandMentions: CommandMentions | undefined;
  readonly onOpenImage: ((image: ImageContent) => void) | undefined;
  readonly onCopy: ((text: string) => Promise<void>) | undefined;
  /** Which tokens of a sent message get a styled treatment (`@path` mentions, a leading `/skill`). */
  readonly pieces: { readonly mentions: boolean; readonly uploads?: boolean; readonly skills: readonly string[]; readonly openMention?: ((path: string) => void) | undefined; readonly renderMention?: ((path: string) => ReactNode | undefined) | undefined;
    readonly preview?: PreviewRead | undefined } | undefined;
  /** Opens an `uploads/` file from its card in a sent message (`PiChat`'s `onOpenFile`). Absent: the card is not clickable. */
  readonly openFile?: ((path: string) => void) | undefined;
  readonly answer: ((questionId: string, answer: string) => Promise<AnswerOutcome>) | undefined;
  readonly artifacts: { readonly open: ArtifactsConfig['open']; readonly isOpen?: ArtifactsConfig['isOpen'] | undefined } | undefined;
  /** Replaces the default copy button under a settled reply (the ambient window adds feedback and the time); `host` holds the host's message actions. */
  readonly replyActions?: ((reply: { readonly key: string; readonly text: string; readonly timestamp?: number | undefined }, host: ReactNode) => ReactNode) | undefined;
  /** The host's actions for a settled reply (`messageActions`). */
  readonly messageActions?: ((reply: ReplyRef) => readonly BlockAction[]) | undefined;
  /** A line under a finished reply (not while it streams, runs a tool or waits to retry), after its actions (a host shows which model answered and how long it took). */
  readonly replyFooter?: ((reply: ReplyRef) => ReactNode) | undefined;
  /** Fork the conversation after a settled reply (its last native entry): adds a Fork button next to Copy. */
  readonly onFork?: ((entryId: string) => void) | undefined;
}

const replyRef = (row: Extract<Row, { type: 'assistant' }>): ReplyRef => ({ key: row.key, text: row.text, entryId: row.entryId, timestamp: row.timestamp, model: row.model, durationMs: row.durationMs });

function Image({ image, onOpenImage }: { readonly image: ImageContent; readonly onOpenImage: RowContext['onOpenImage'] }) {
  const { labels } = useChatText();
  const src = thumbnail(image.mimeType, image.data);
  return <button type="button" data-testid="message-image" disabled={!onOpenImage} aria-label={labels.openImage} onClick={() => onOpenImage?.(image)}
    className="block cursor-pointer overflow-hidden rounded-xl border border-border outline-none focus-visible:ring-2 focus-visible:ring-ring/60 disabled:cursor-default">
    {src ? <img src={src} alt={labels.imageAttachment} className="max-h-48 max-w-full object-cover" /> : <span className="block px-3 py-2 text-xs text-muted-foreground">{labels.imageAttachment}</span>}
  </button>;
}

const MENTION_CLASS = 'rounded-md bg-background px-1.5 py-0.5 font-mono text-sm font-medium text-foreground ring-1 ring-border';

/** A `@path` mention in a sent message: the host's own look when its `render` returns one, else the default chip (a button when it can be opened). */
function UserMention({ path, text, open, render }: { readonly path: string; readonly text: string; readonly open: ((path: string) => void) | undefined; readonly render: ((path: string) => ReactNode | undefined) | undefined }) {
  const custom = render?.(path);
  if (custom !== undefined) return <>{custom}</>;
  return open
    ? <button type="button" data-testid="message-mention" data-path={path} aria-label={`Open ${path}`} onClick={() => open(path)} className={cn(MENTION_CLASS, 'cursor-pointer outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60 pointer-coarse:inline-flex pointer-coarse:min-h-10 pointer-coarse:items-center')}>{text}</button>
    : <span data-testid="message-mention" data-path={path} className={MENTION_CLASS}>{text}</span>;
}

/** The icon a file card shows for its kind. */
function FileGlyph({ kind }: { readonly kind: FileKind }) {
  const className = 'size-5 text-muted-foreground';
  switch (kind) {
    case 'image': return <ImageIcon className={className} aria-hidden="true" />;
    case 'sheet': return <FileSpreadsheetIcon className={className} aria-hidden="true" />;
    case 'slides': return <PresentationIcon className={className} aria-hidden="true" />;
    case 'document': return <FileTextIcon className={className} aria-hidden="true" />;
    default: return <FileIcon className={className} aria-hidden="true" />;
  }
}

/** A file a person sent (an `uploads/` mention): its icon or thumbnail, name and type. A button when it can be opened. */
function FileCard({ path, open, preview }: { readonly path: string; readonly open: ((path: string) => void) | undefined; readonly preview: PreviewRead | undefined }) {
  const { labels } = useChatText();
  const kind = fileKind(path), name = displayName(path);
  const [src, setSrc] = useState<string | undefined>();
  // A thumbnail belongs to the provider that read it: a new provider, or a read that is refused or unavailable, shows the icon.
  useEffect(() => {
    setSrc(undefined);
    if (kind !== 'image' || !preview) return;
    const abort = new AbortController();
    preview(path, abort.signal).then(
      read => { if (!abort.signal.aborted) setSrc(read ? thumbnail(read.mimeType, read.data) : undefined); },
      () => { if (!abort.signal.aborted) setSrc(undefined); });
    return () => abort.abort();
  }, [kind, path, preview]);
  const body = <>
    <span className="flex size-11 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-background ring-1 ring-border">
      {src ? <img src={src} alt="" className="size-full object-cover" /> : <FileGlyph kind={kind} />}
    </span>
    <span className="flex min-w-0 flex-col text-left">
      <span className="truncate text-sm font-medium text-foreground">{name}</span>
      <span className="truncate text-xs text-muted-foreground">{labels.fileKind[kind]}</span>
    </span>
  </>;
  return open
    // The card keeps the `message-mention` test id of the chip it replaces, so a journey that clicks a sent mention still finds it.
    ? <button type="button" data-testid="message-mention" data-path={path} aria-label={labels.openFile(name)} onClick={() => open(path)}
      className="flex min-h-11 max-w-[16rem] cursor-pointer items-center gap-2.5 rounded-xl border border-border bg-card p-1.5 pr-3 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60">{body}</button>
    : <div data-testid="message-mention" data-path={path} className="flex min-h-11 max-w-[16rem] items-center gap-2.5 rounded-xl border border-border bg-card p-1.5 pr-3">{body}</div>;
}

/** The file cards of a message, above its text bubble. */
function FileCards({ paths, open, preview }: { readonly paths: readonly string[]; readonly open: ((path: string) => void) | undefined; readonly preview: PreviewRead | undefined }) {
  return <ul data-testid="message-files" className="m-0 flex max-w-[85%] list-none flex-wrap justify-end gap-2 p-0">
    {paths.map(path => <li key={path} data-testid="message-file"><FileCard path={path} open={open} preview={preview} /></li>)}
  </ul>;
}

/**
 * A text part of a sent message. Its `uploads/` mentions become file cards above the bubble and leave the text; the message content keeps
 * them (only what is drawn changes).
 */
function UserText({ text, context }: { readonly text: string; readonly context: RowContext }) {
  const open = context.pieces?.openMention;
  const render = context.pieces?.renderMention;
  const bubble = 'max-w-[85%] rounded-2xl rounded-br-md bg-muted px-4 py-2.5 text-sm leading-6 whitespace-pre-wrap text-foreground [overflow-wrap:anywhere]';
  if (!context.pieces) return <div data-testid="user-text" className={bubble}>{text}</div>;
  const all = pieces(text, context.pieces);
  const isFile = (piece: Piece) => piece.kind === 'mention' && isUploadPath(piece.value!);
  const files = all.filter(isFile).map(piece => piece.value!);
  const shown = files.length ? visibleParts(all, isFile) : all;
  const empty = shown.every(piece => piece.kind === undefined && piece.text === '');
  return <>
    {files.length > 0 && <FileCards paths={files} open={context.openFile ?? open} preview={context.pieces.preview} />}
    {!(files.length > 0 && empty) && <div data-testid="user-text" className={bubble}>{shown.map((piece, at) => piece.kind === 'mention'
      ? <UserMention key={at} path={piece.value!} text={piece.text} open={open} render={render} />
      : piece.kind === 'skill' ? <span key={at} data-testid="message-skill" data-skill={piece.value} className="rounded-md bg-primary/10 px-1.5 py-0.5 font-medium text-foreground">{piece.text}</span>
      : piece.text)}</div>}
  </>;
}

function UserBubble({ message, context }: { readonly message: UserMessage; readonly context: RowContext }) {
  const parts = typeof message.content === 'string' ? [{ type: 'text' as const, text: message.content }] : message.content;
  return <div className="flex flex-col items-end gap-2">
    {parts.map((part, index) => part.type === 'text' ? (isFileBlock(part.text) ? null : <UserText key={index} text={part.text} context={context} />)
      : <Image key={index} image={part} onOpenImage={context.onOpenImage} />)}
  </div>;
}

function Notice({ tone, icon, children, testid }: { readonly tone: 'error' | 'muted'; readonly icon: ReactNode; readonly children: ReactNode; readonly testid: string }) {
  return <p role={tone === 'error' ? 'alert' : 'status'} data-testid={testid}
    className={cn('my-2 mb-0 flex items-start gap-2 rounded-lg px-3 py-2 text-sm', tone === 'error' ? 'bg-destructive/10 text-destructive' : 'bg-muted/60 text-muted-foreground')}>{icon}<span className="min-w-0 [overflow-wrap:anywhere]">{children}</span></p>;
}

function resultText(message: ToolResultMessage): string { return message.content.map(part => part.type === 'text' ? part.text : '').join('\n'); }

export function RowView({ row, context }: { readonly row: Row; readonly context: RowContext }) {
  const { labels, icons } = useChatText();
  switch (row.type) {
    case 'user': return <article data-row-id={row.key} data-role="user"><UserBubble message={row.message} context={context} /></article>;
    case 'card': return <article data-row-id={row.key} data-role="event">{row.card.content}</article>;
    case 'event': return <article data-row-id={row.key} data-role="event" className="text-center text-xs text-muted-foreground">{labels.event(row.label)}</article>;
    case 'system': return <article data-row-id={row.key} data-role="system"><details className="rounded-lg border border-border bg-muted/30 px-3 py-2 text-xs text-muted-foreground"><summary className="cursor-pointer max-sm:py-3 pointer-coarse:py-3">{labels.systemContext}</summary>
      <pre className="mt-2 mb-0 whitespace-pre-wrap">{row.text}</pre></details></article>;
    case 'orphan-result': return <article data-row-id={row.key} data-role="toolResult"><Notice tone="error" testid="tool-error" icon={<AlertCircleIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>
      <strong className="font-semibold">{labels.toolFailed(row.message.toolName)}</strong><span className="mt-1 block font-mono text-xs whitespace-pre-wrap">{resultText(row.message)}</span></Notice></article>;
    case 'assistant': {
      const settled = !row.streaming;
      const chunks = segments(row.parts, context.groupTool);
      const active = row.active === true || row.streaming;
      const lastText = [...row.parts].reverse().find(part => part.kind === 'text');
      const host = settled && row.text && context.messageActions
        ? <BlockActions actions={context.messageActions(replyRef(row))} testId="reply-action" menuLabel={labels.moreActions} className="text-muted-foreground" />
        : null;
      return <article data-row-id={row.key} data-role="assistant" data-streaming={row.streaming ? 'true' : undefined} className="group/message">
        <div className="space-y-3">
          {chunks.map((chunk, at) => {
            if (chunk.kind === 'activity') {
              const failed = chunk.steps.some(step => step.kind === 'tool' && step.entry.status === 'failed');
              const unfinished = chunk.steps.some(step => step.kind === 'tool' && step.entry.status === 'unfinished');
              const state: ActivityState = failed || row.stopReason === 'error' ? 'failed' : row.stopReason === 'aborted' || (!active && unfinished) ? 'stopped' : active && at === chunks.length - 1 ? 'running' : 'done';
              return <ActivityBlock key={chunk.key} steps={chunk.steps} state={state} streaming={row.streaming} developer={context.developer} {...(context.onOpenImage ? { onOpenImage: context.onOpenImage } : {})} />;
            }
            const part = chunk.part;
            if (part.kind === 'text') return <Markdown key={part.key} text={part.text} streaming={row.streaming && part === lastText && row.parts[row.parts.length - 1] === part}
              {...(settled && context.commandMentions ? { commandMentions: context.commandMentions } : {})} {...(context.onCopy ? { onCopy: context.onCopy } : {})} />;
            if (part.kind === 'thinking') return null; // reasoning is a step of an activity block
            if (part.kind === 'approval') return <ApprovalCard key={part.key} call={part.call} result={part.result} questionId={part.questionId} answer={context.answer} summary={part.summary} decision={part.decision} live={part.live} />;
            if (part.kind === 'question') return <QuestionCard key={part.key} call={part.call} result={part.result} questionId={part.questionId} answer={context.answer} live={part.live} />;
            if (part.kind === 'artifact') return <ArtifactCard key={part.key} artifact={part.artifact} title={part.title} {...(part.state === 'ready' ? {} : { pending: part.state })}
              open={part.artifact !== undefined && (context.artifacts?.isOpen?.(part.artifact) ?? false)} onOpen={context.artifacts?.open} />;
            return part.entry.custom ? <div key={part.key}>{part.entry.custom}</div> : <ToolCard key={part.key} entry={part.entry} {...(context.onOpenImage ? { onOpenImage: context.onOpenImage } : {})} />;
          })}
          {row.streaming && row.parts.length === 0 && <p data-testid="working" className="m-0 text-sm"><Shimmer>{labels.thinking}</Shimmer></p>}
        </div>
        {row.stopReason === 'error' && <Notice tone="error" testid="response-error" icon={<AlertCircleIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>{row.errorMessage ?? labels.responseFailed}</Notice>}
        {row.stopReason === 'aborted' && <Notice tone="muted" testid="interrupted" icon={<CircleSlashIcon className="mt-0.5 size-4 shrink-0" aria-hidden="true" />}>{labels.interrupted}</Notice>}
        {settled && row.text && context.replyActions?.({ key: row.key, text: row.text, timestamp: row.timestamp }, host)}
        {settled && row.text && !context.replyActions && <div className="mt-1 -ml-2 flex opacity-0 transition-opacity group-focus-within/message:opacity-100 group-hover/message:opacity-100 pointer-coarse:opacity-100 max-sm:opacity-100 motion-reduce:transition-none">
          <CopyButton text={row.text} label={labels.copyResponse} {...(context.onCopy ? { onCopy: context.onCopy } : {})} className="text-muted-foreground" />
          {context.onFork && row.entryId && <Button size="icon-sm" variant="ghost" aria-label={labels.fork} title={labels.forkHint} data-testid="fork-reply"
            className="text-muted-foreground" onClick={() => context.onFork!(row.entryId!)}><icons.fork className="size-3.5" aria-hidden="true" /></Button>}
          {host}</div>}
        {settled && !row.active && row.text && context.replyFooter?.(replyRef(row))}
      </article>;
    }
  }
}

