import { useEffect, useRef } from 'react';
import type { Dispatch, RefObject, SetStateAction } from 'react';

/**
 * Keyboard navigation for a floating picker, ported from v2's `use-picker-keyboard`. It listens on the window in the
 * capture phase and stops handled keys, so the textarea keeps focus and Enter does not also send the message.
 */
export function usePickerKeyboard({ count, activeIdx, setActiveIdx, listRef, onSelect, onDismiss }: {
  readonly count: number;
  readonly activeIdx: number;
  readonly setActiveIdx: Dispatch<SetStateAction<number>>;
  readonly listRef: RefObject<HTMLElement | null>;
  readonly onSelect: (index: number) => void;
  readonly onDismiss: () => void;
}) {
  const select = useRef(onSelect), dismiss = useRef(onDismiss);
  select.current = onSelect; dismiss.current = onDismiss;
  useEffect(() => {
    const handler = (event: KeyboardEvent) => {
      if (event.isComposing) return;
      const handled = () => { event.preventDefault(); event.stopPropagation(); };
      if (event.key === 'ArrowDown') { handled(); setActiveIdx(index => count === 0 ? 0 : (index + 1) % count); }
      else if (event.key === 'ArrowUp') { handled(); setActiveIdx(index => count === 0 ? 0 : (index - 1 + count) % count); }
      else if (event.key === 'Enter' || event.key === 'Tab') {
        if (count > 0) { handled(); select.current(activeIdx); }
        // Nothing to pick: close and let the key reach the textarea (Enter then sends as usual).
        else dismiss.current();
      } else if (event.key === 'Escape') { handled(); dismiss.current(); }
    };
    window.addEventListener('keydown', handler, { capture: true });
    return () => window.removeEventListener('keydown', handler, { capture: true });
  }, [count, activeIdx, setActiveIdx]);
  useEffect(() => { (listRef.current?.children[activeIdx] as HTMLElement | undefined)?.scrollIntoView({ block: 'nearest' }); }, [activeIdx, listRef]);
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { CheckIcon, ChevronDownIcon, Loader2Icon } from 'lucide-react';
import type { EffortConfig, ModelConfig, ModelRef } from './config';
import { cn } from '../utils/utils';
import { useChatText } from './labels';

interface Choice { readonly section: 'model' | 'effort'; readonly value: string; readonly label: string; readonly detail?: string }

const key = (model: ModelRef) => `${model.provider}/${model.modelId}`;

/**
 * One pill for the model and the thinking level ("GPT-5 mini · Medium") that opens one listbox with a section for each
 * (arrow keys, Enter, Escape, outside click). Only the configured parts show; with neither there is no pill.
 */
export function ModelEffortPicker({ model, effort, currentModel, currentEffort, disabled, busy, onModel, onEffort }: {
  readonly model: ModelConfig | undefined; readonly effort: EffortConfig | undefined;
  readonly currentModel: ModelRef | undefined; readonly currentEffort: string | undefined;
  readonly disabled: boolean; readonly busy: 'model' | 'effort' | null;
  readonly onModel: (model: ModelRef) => void; readonly onEffort: (level: string) => void;
}) {
  const { labels } = useChatText();
  const name = labels.effortName;
  const models: Choice[] = (model?.options ?? []).map(option => ({ section: 'model', value: key(option), label: option.label ?? option.modelId, detail: option.provider }));
  // A model or level outside the offered list is still shown, so the label never lies about what runs.
  if (model && currentModel && !models.some(choice => choice.value === key(currentModel))) models.unshift({ section: 'model', value: key(currentModel), label: currentModel.modelId, detail: currentModel.provider });
  const levels: Choice[] = (effort?.options ?? []).map(level => ({ section: 'effort', value: level, label: name(level), ...(labels.effortDetail(level) ? { detail: labels.effortDetail(level)! } : {}) }));
  if (effort && currentEffort && !levels.some(choice => choice.value === currentEffort)) levels.unshift({ section: 'effort', value: currentEffort, label: name(currentEffort) });
  const choices = [...models, ...levels];
  const modelValue = currentModel ? key(currentModel) : '';
  const isCurrent = (choice: Choice) => choice.value === (choice.section === 'model' ? modelValue : currentEffort);

  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const root = useRef<HTMLDivElement>(null), list = useRef<HTMLUListElement>(null), trigger = useRef<HTMLButtonElement>(null);
  const selected = Math.max(0, choices.findIndex(isCurrent));
  const close = () => { setOpen(false); trigger.current?.focus(); };
  useEffect(() => {
    if (!open) return;
    setActive(selected);
    const outside = (event: MouseEvent) => { if (root.current && !root.current.contains(event.target as Node)) setOpen(false); };
    document.addEventListener('mousedown', outside);
    return () => document.removeEventListener('mousedown', outside);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);
  useEffect(() => { if (open) list.current?.querySelector<HTMLElement>('[data-active=true]')?.scrollIntoView({ block: 'nearest' }); }, [open, active]);
  useEffect(() => { if (disabled) setOpen(false); }, [disabled]);
  if (!choices.length) return null;

  const choose = (index: number) => {
    const choice = choices[index];
    setOpen(false);
    if (!choice || isCurrent(choice)) return;
    if (choice.section === 'effort') return onEffort(choice.value);
    const option = model?.options.find(item => key(item) === choice.value);
    if (option) onModel({ provider: option.provider, modelId: option.modelId });
  };
  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!open) return;
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive(index => (index + 1) % choices.length); }
    else if (event.key === 'ArrowUp') { event.preventDefault(); setActive(index => (index - 1 + choices.length) % choices.length); }
    else if (event.key === 'Enter' || event.key === ' ' || event.key === 'Tab') { event.preventDefault(); choose(active); trigger.current?.focus(); }
    else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
  };
  const modelLabel = model ? models.find(choice => choice.value === modelValue)?.label || currentModel?.modelId || labels.model : undefined;
  const effortLabel = effort ? currentEffort ? name(currentEffort) : labels.effortDefault : undefined;
  const summary = [modelLabel, effortLabel].filter(Boolean).join(' · ');
  const description = labels.modelSummary(modelLabel, effortLabel);
  const row = (choice: Choice, index: number) => <li key={`${choice.section}:${choice.value}`} role="option" aria-selected={isCurrent(choice)} data-testid={`composer-${choice.section}-option`} data-value={choice.value} data-active={index === active}
    onMouseEnter={() => setActive(index)} onMouseDown={event => { event.preventDefault(); choose(index); trigger.current?.focus(); }}
    className={cn('flex cursor-pointer items-center gap-2 rounded-lg px-2.5 py-1.5 text-sm max-sm:min-h-11 pointer-coarse:min-h-11', index === active ? 'bg-accent text-foreground' : 'text-muted-foreground')}>
    <span className="flex min-w-0 flex-1 flex-col"><span className="truncate font-medium text-foreground">{choice.label}</span>
      {choice.detail && <span className="truncate text-xs opacity-70">{choice.detail}</span>}</span>
    {isCurrent(choice) && <CheckIcon className="size-4 shrink-0" aria-hidden="true" />}
  </li>;
  const section = (title: string, items: readonly Choice[], offset: number) => items.length > 0 && <li role="presentation" key={title}>
    <ul role="group" aria-label={title} className="m-0 list-none p-0">
      <li role="presentation" className="px-2.5 pt-1.5 pb-1 text-xs font-medium text-muted-foreground">{title}</li>
      {items.map((choice, index) => row(choice, offset + index))}
    </ul></li>;
  return <div ref={root} className="relative min-w-0 shrink" onKeyDown={onKeyDown}>
    <button ref={trigger} type="button" data-testid="composer-model" data-value={modelValue} data-effort={currentEffort ?? ''} disabled={disabled} aria-haspopup="listbox" aria-expanded={open} aria-label={description} title={description}
      onClick={() => setOpen(value => !value)}
      className="inline-flex h-11 min-w-0 max-w-full cursor-pointer items-center gap-1.5 rounded-full bg-muted px-4 text-sm font-medium text-foreground transition-colors outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60 disabled:cursor-not-allowed disabled:opacity-60 motion-reduce:transition-none max-sm:px-3">
      {busy && <Loader2Icon className="size-3.5 shrink-0 animate-spin motion-reduce:animate-none" aria-hidden="true" />}
      <span data-testid="composer-model-label" className="min-w-0 truncate">{summary}</span>
      <ChevronDownIcon className="size-3.5 shrink-0 opacity-50" aria-hidden="true" />
    </button>
    {open && <ul ref={list} role="listbox" aria-label={labels.modelAndEffort} data-testid="composer-model-menu" className="absolute bottom-full left-0 z-20 mb-2 m-0 max-h-80 min-w-56 list-none overflow-y-auto rounded-2xl border border-border bg-popover p-1.5 text-popover-foreground shadow-lg max-sm:fixed max-sm:inset-x-0 max-sm:bottom-0 max-sm:mb-0 max-sm:max-h-[70dvh] max-sm:rounded-b-none max-sm:p-2 max-sm:pb-[max(0.5rem,env(safe-area-inset-bottom))]">
      {model && section(labels.model, models, 0)}
      {effort && section(labels.effort, levels, models.length)}
    </ul>}
  </div>;
}

'use client';

import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import type { ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import { CheckIcon, MessageCircleQuestionIcon, SendIcon } from 'lucide-react';
import { Button } from '../button/button';
import { cn } from '../utils/utils';
import { useChatText } from './labels';

/** What the host answers when asked to resolve a pending question. */
export type AnswerOutcome = { readonly kind: 'answered' } | { readonly kind: 'denied' | 'conflict' | 'unknown-question'; readonly reason?: string };
export const ASK_USER_TOOL = 'ask_user';

interface Question { readonly question: string; readonly options: readonly string[]; readonly allowFreeText: boolean }

/** Read `{ question, options?, allowFreeText? }` defensively: model arguments are untrusted input. */
export function parseQuestion(call: ToolCall): Question {
  const args = call.arguments as Record<string, unknown>;
  const options = Array.isArray(args['options']) ? args['options'].filter((item): item is string => typeof item === 'string' && item.length > 0).slice(0, 6) : [];
  return { question: typeof args['question'] === 'string' ? args['question'] : '', options, allowFreeText: args['allowFreeText'] === true };
}

/** The answered text from a result such as `{"kind":"answered","answer":"..."}`; undefined when the call did not produce an answer. */
export function parseAnswer(result: ToolResultMessage | undefined): { readonly answer: string } | { readonly failure: string } | undefined {
  if (!result) return undefined;
  const text = result.content.map(part => part.type === 'text' ? part.text : '').join('');
  if (!result.isError) {
    try {
      const value: unknown = JSON.parse(text);
      if (value !== null && typeof value === 'object' && (value as { kind?: unknown }).kind === 'answered' && typeof (value as { answer?: unknown }).answer === 'string') return { answer: (value as { answer: string }).answer };
    } catch { /* fall through to the failure text */ }
  }
  return { failure: text || 'The question was not answered.' };
}


/** Human-in-the-loop question: writing (still generated, not answerable), pending (options and optional free text), then answered with the chosen answer. */
export function QuestionCard({ call, result, answer, questionId, live = false }: {
  readonly call: ToolCall;
  readonly result: ToolResultMessage | undefined;
  readonly questionId: string | undefined;
  readonly answer?: ((questionId: string, answer: string) => Promise<AnswerOutcome>) | undefined;
  /** The call is still being generated by the model: it cannot be answered yet. */
  readonly live?: boolean;
}) {
  const { labels } = useChatText();
  const question = parseQuestion(call);
  const settled = parseAnswer(result);
  const [sent, setSent] = useState<string | undefined>();
  const [sending, setSending] = useState<string | undefined>();
  const [refusal, setRefusal] = useState<string | undefined>();
  const [text, setText] = useState('');
  const mounted = useRef(true);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  const current = settled && 'answer' in settled ? settled.answer : sent;
  // `pending` means the question waits on the person; `writing` means the model is still generating it (options may be partial).
  const state = settled ? ('failure' in settled ? 'failed' : 'answered') : sent !== undefined ? 'sent' : live ? 'writing' : 'pending';
  const open = state === 'pending' || state === 'writing';

  async function submit(value: string) {
    const trimmed = value.trim();
    if (!answer || !questionId || live || !trimmed || sending !== undefined) return;
    setRefusal(undefined); setSending(trimmed);
    try {
      const outcome = await answer(questionId, trimmed);
      if (outcome.kind === 'answered') setSent(trimmed);
      else setRefusal(outcome.reason || labels.answerRefused(outcome.kind));
    } catch (cause) { setRefusal(cause instanceof Error ? cause.message : labels.answerNotSent); }
    finally { if (mounted.current) setSending(undefined); }
  }
  const onSubmit = (event: FormEvent) => { event.preventDefault(); void submit(text); };
  const busy = sending !== undefined || live;

  return <section data-testid="question-card" data-state={state} data-call-id={call.id} aria-label={labels.question}
    className={cn('my-2 rounded-xl border bg-card p-4 text-card-foreground shadow-xs', open ? 'border-ring/50' : 'border-border')}>
    <div className="flex items-start gap-3">
      <span className={cn('mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-lg', open ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground')}>
        {state === 'answered' || state === 'sent' ? <CheckIcon className="size-4" aria-hidden="true" /> : <MessageCircleQuestionIcon className="size-4" aria-hidden="true" />}
      </span>
      <div className="min-w-0 flex-1">
        <p className="m-0 text-xs font-medium tracking-wider text-muted-foreground uppercase">{open ? labels.questionForYou : state === 'failed' ? labels.notAnswered : labels.answered}</p>
        <p data-testid="question-text" className="mt-1 mb-0 text-sm leading-6 font-medium [overflow-wrap:anywhere]">{question.question || labels.askedQuestion}</p>

        {open && <>
          {question.options.length > 0 && <div role="group" aria-label={labels.answerOptions} className="mt-3 flex flex-wrap gap-2">
            {question.options.map(option => <Button key={option} variant="outline" data-testid="question-option" data-option={option} disabled={!answer || !questionId || busy}
              onClick={() => { void submit(option); }} className={cn('h-auto min-h-11 max-w-full py-1.5 whitespace-normal sm:min-h-9', sending === option && 'border-ring')}>{option}</Button>)}
          </div>}
          {question.allowFreeText && <form onSubmit={onSubmit} className="mt-3 flex gap-2">
            <input data-testid="question-input" value={text} maxLength={2000} disabled={!answer || !questionId || busy} placeholder={question.options.length ? labels.ownAnswer : labels.typeAnswer}
              aria-label={labels.yourAnswerInput} onChange={event => setText(event.currentTarget.value)}
              className="h-11 min-w-0 flex-1 rounded-lg border border-input bg-background px-3 text-base outline-none sm:h-9 sm:text-sm placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring/60 disabled:opacity-50" />
            <Button type="submit" variant="default" data-testid="question-submit" disabled={!answer || !questionId || busy || !text.trim()}><SendIcon className="size-3.5" aria-hidden="true" />{labels.answer}</Button>
          </form>}
          {live && <p className="mt-3 mb-0 text-xs text-muted-foreground">{labels.stillWritingQuestion}</p>}
          {!answer && !live && <p className="mt-3 mb-0 text-xs text-muted-foreground">{labels.answeringUnavailable}</p>}
        </>}

        {(state === 'answered' || state === 'sent') && current !== undefined && <p className="mt-2 mb-0 text-sm text-muted-foreground">{labels.yourAnswer} <span data-testid="question-answer" className="rounded-md bg-muted px-1.5 py-0.5 font-medium text-foreground [overflow-wrap:anywhere]">{current}</span>
          {state === 'sent' && <span className="ms-2 text-xs">{labels.waitingForAgent}</span>}</p>}
        {state === 'failed' && settled && 'failure' in settled && <p role="alert" className="mt-2 mb-0 text-sm text-destructive">{settled.failure}</p>}
        {refusal && open && <p role="alert" data-testid="question-refusal" className="mt-3 mb-0 rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">{refusal}</p>}
      </div>
    </div>
  </section>;
}

'use client';

import { useEffect, useRef, useState } from 'react';
import type { ChatDraft } from '@hachej/boring-ui-kit/native-chat';
import { CornerDownRightIcon, EllipsisIcon, ListEndIcon, LoaderIcon, PencilIcon, RouteIcon, Trash2Icon } from 'lucide-react';
import { isFileBlock, type QueuedMessage } from './rows';
import { defaultChatLabels, useChatText } from './labels';

export type { QueuedMessage } from './rows';

/** Display text of a queued submission: the text parts of its content, plus a count of images. */
export function queuedText(item: QueuedMessage, imagesLabel: (count: number) => string = defaultChatLabels.images): string {
  const content = item.content as unknown;
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  const parts = content as readonly { type?: unknown; text?: unknown }[];
  const text = parts.flatMap(part => part?.type === 'text' && typeof part.text === 'string' && !isFileBlock(part.text) ? [part.text] : []).join('\n');
  const images = parts.filter(part => part?.type === 'image').length;
  return images ? `${text}${text ? '\n' : ''}${imagesLabel(images)}` : text;
}

/** What a queued message can be taken back for. Both take the message out of the queue first and throw when it is too late. */
export interface QueueActions {
  /** Take it out of the queue and put its text (and images) back in the composer. */
  readonly edit?: ((item: QueuedMessage) => Promise<void>) | undefined;
  /** Take it out of the queue and send it into the running turn now. */
  readonly steer?: ((item: QueuedMessage) => Promise<void>) | undefined;
}

const rowButton = 'inline-flex shrink-0 cursor-pointer items-center justify-center gap-1 rounded-lg text-muted-foreground outline-none transition-colors hover:bg-background/70 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 disabled:pointer-events-none disabled:opacity-45 motion-reduce:transition-none';

/** The "…" button of one queued message: a small menu of the secondary actions (Edit). */
function MoreMenu({ disabled, onEdit }: { readonly disabled: boolean; readonly onEdit: () => void }) {
  const { labels } = useChatText();
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null), trigger = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!open) return;
    const outside = (event: MouseEvent) => { if (root.current && !root.current.contains(event.target as Node)) setOpen(false); };
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape') { event.stopPropagation(); setOpen(false); trigger.current?.focus(); } };
    document.addEventListener('mousedown', outside); document.addEventListener('keydown', escape, true);
    return () => { document.removeEventListener('mousedown', outside); document.removeEventListener('keydown', escape, true); };
  }, [open]);
  return <div ref={root} className="relative shrink-0">
    <button ref={trigger} type="button" data-testid="queue-more" aria-label={labels.moreActions} title={labels.more} aria-haspopup="menu" aria-expanded={open} disabled={disabled} onClick={() => setOpen(value => !value)}
      className={`${rowButton} size-8 max-sm:size-10`}><EllipsisIcon className="size-4" aria-hidden="true" /></button>
    {open && <div role="menu" data-testid="queue-menu" className="absolute right-0 bottom-full z-30 mb-1 w-40 rounded-xl border border-border bg-popover p-1 text-popover-foreground shadow-lg">
      <button type="button" role="menuitem" data-testid="queue-edit" autoFocus onClick={() => { setOpen(false); onEdit(); }}
        className="flex min-h-9 w-full cursor-pointer items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-sm text-foreground outline-none hover:bg-accent focus-visible:bg-accent max-sm:min-h-10"><PencilIcon className="size-3.5 text-muted-foreground" aria-hidden="true" />{labels.edit}</button>
    </div>}
  </div>;
}

/**
 * Messages sent while the agent was working, waiting for Pi to place them, drawn as a slim tab tucked behind the top edge of the composer
 * (render it directly above `Composer`; the composer overlaps its bottom). One row per message: icon, text, Steer, remove and a "…" menu
 * (Edit). The choice is made here, per message, never in the composer. Rows leave on their own once Pi starts them. `sending` are messages
 * sent from the composer that wait for the previous send to be confirmed (the controller's `outbox`): shown last, without actions.
 */
export function MessageQueue({ items, sending = [], withdraw, actions }: {
  readonly items: readonly QueuedMessage[];
  readonly sending?: readonly ChatDraft[] | undefined;
  readonly withdraw?: ((id: QueuedMessage['id']) => Promise<unknown>) | undefined;
  readonly actions?: QueueActions | undefined;
}) {
  const { labels } = useChatText();
  const [failed, setFailed] = useState<string | undefined>();
  const [busy, setBusy] = useState<ReadonlySet<string>>(new Set());
  if (!items.length && !sending.length) return null;
  async function run(item: QueuedMessage, work: () => Promise<unknown>) {
    const id = String(item.id);
    setFailed(undefined); setBusy(current => new Set(current).add(id));
    try { await work(); }
    catch (cause) { setFailed(cause instanceof Error ? cause.message : labels.queueFailed); }
    finally { setBusy(current => { const next = new Set(current); next.delete(id); return next; }); }
  }
  const remove = (item: QueuedMessage) => run(item, async () => {
    const outcome = await withdraw!(item.id);
    if (outcome === 'already_placed' || outcome === 'settled') throw new Error(labels.tooLateToRemove);
  });
  return <section data-testid="queue" aria-label={labels.queuedMessages} className="relative mx-3 -mb-3 rounded-t-2xl border border-b-0 border-border bg-muted pb-3 text-foreground">
    <ul className="m-0 list-none p-0">
      {items.map((item, index) => {
        const working = busy.has(String(item.id));
        const steering = item.mode === 'steer';
        return <li key={String(item.id)} data-testid="queue-item" data-mode={item.mode} className={`flex min-h-10 items-center gap-1.5 pr-1.5 pl-3 ${index > 0 ? 'border-t border-border/70' : ''}`}>
          {steering ? <RouteIcon className="size-4 shrink-0 text-muted-foreground" aria-label={labels.steering} /> : <ListEndIcon className="size-4 shrink-0 text-muted-foreground" aria-label={labels.queued} />}
          <span data-testid="queue-text" className="min-w-0 flex-1 truncate px-1 text-sm">{queuedText(item, labels.images)}</span>
          {!steering && actions?.steer && <button type="button" data-testid="queue-steer" title={labels.steerHint} disabled={working} onClick={() => { void run(item, () => actions.steer!(item)); }}
            className={`${rowButton} h-8 px-2 text-sm max-sm:h-10 max-sm:px-2.5`}><CornerDownRightIcon className="size-3.5" aria-hidden="true" />{labels.steer}</button>}
          {steering && <span className="shrink-0 px-1 text-xs text-muted-foreground">{labels.steering}</span>}
          <button type="button" data-testid="queue-cancel" aria-label={labels.removeQueued} title={labels.removeHint} disabled={!withdraw || working} onClick={() => { void remove(item); }}
            className={`${rowButton} size-8 max-sm:size-10`}><Trash2Icon className="size-3.5" aria-hidden="true" /></button>
          {actions?.edit && <MoreMenu disabled={working} onEdit={() => { void run(item, () => actions.edit!(item)); }} />}
        </li>;
      })}
      {sending.map((draft, index) => <li key={`sending-${index}`} data-testid="queue-sending" className={`flex min-h-10 items-center gap-1.5 pr-1.5 pl-3 ${items.length + index > 0 ? 'border-t border-border/70' : ''}`}>
        <LoaderIcon className="size-4 shrink-0 animate-spin text-muted-foreground motion-reduce:animate-none" aria-label={labels.sending} />
        <span data-testid="queue-text" className="min-w-0 flex-1 truncate px-1 text-sm">{draft.text}{draft.attachments.length ? `${draft.text ? '\n' : ''}${labels.images(draft.attachments.length)}` : ''}</span>
        <span className="shrink-0 px-1 text-xs text-muted-foreground">{labels.sending}</span>
      </li>)}
    </ul>
    {failed && <p role="alert" data-testid="queue-error" className="m-0 border-t border-border/70 px-3 py-2 text-xs text-destructive">{failed}</p>}
  </section>;
}

import type { ReactNode } from 'react';
import type { ConversationView, EntryRecord, InboxItem, JsonObject } from '@earendil-works/pi-durable';
import type { JsonValue } from '@earendil-works/chord';
import type { AssistantMessage, Message, ToolCall, ToolResultMessage, UserMessage } from '@earendil-works/pi-ai';
import type { ToolEntry, ToolStatus } from './tool';
import { ASK_USER_TOOL } from './question-card';
import { PRESENT_TOOL, artifactKey, detectArtifact, pendingId, pendingTitle } from './artifact';
import type { ArtifactDescriptor, ArtifactsConfig } from './artifact';

/** The host adds file content for `@path` mentions as parts that start like this; the message already shows the mention itself. */
export const isFileBlock = (text: string): boolean => text.startsWith('<file path="');

/** A submission waiting in the native inbox (steer or follow-up); `queuedMessages` reads them from the view, the queue renders them. */
export type QueuedMessage = Extract<InboxItem, { readonly mode: 'steer' | 'followUp' }>;

/*
 * The one message model is the native Pi view: entries (with their model messages) plus the live `pi.live` document.
 * This module turns a view into display rows with these semantics: tool calls are matched with tool results, expert mode hides successful tool details, the live
 * generation is appended as a streaming row whose key matches the row its committed message will take.
 */
/** `required` pins the card above the transcript. `inline` (tool cards) keeps it in place in expert mode too, like the
 * question and artifact cards; other custom tool cards show only in developer mode or on failure. */
export interface ChatCard { readonly content: ReactNode; readonly required?: boolean; readonly inline?: boolean }
export type Mode = 'expert' | 'developer';
export type StreamPart = { readonly type: 'text'; readonly text: string } | { readonly type: 'thinking'; readonly thinking: string } | ToolCall;

export type Part =
  | { readonly kind: 'text'; readonly key: string; readonly text: string }
  | { readonly kind: 'thinking'; readonly key: string; readonly text: string; readonly streaming: boolean }
  | { readonly kind: 'question'; readonly key: string; readonly call: ToolCall; readonly result: ToolResultMessage | undefined; readonly live: boolean; readonly questionId: string | undefined }
  | { readonly kind: 'approval'; readonly key: string; readonly call: ToolCall; readonly result: ToolResultMessage | undefined; readonly live: boolean; /** The bound question ID the answer must use (as for `question`). */ readonly questionId: string | undefined; /** The one-line summary `requireApproval` published for this call. */ readonly summary: string; /** The decision it recorded, once made. */ readonly decision?: ApprovalDecision; /** The call's own step, shown in the activity block once it has a result. */ readonly entry?: ToolEntry }
  | { readonly kind: 'artifact'; readonly key: string; readonly call: ToolCall; readonly state: 'presenting' | 'ready'; readonly artifact: ArtifactDescriptor | undefined; readonly title: string | undefined; /** Set when the host's `detect` found the descriptor: the call stays a step of the activity block too. */ readonly entry?: ToolEntry }
  | { readonly kind: 'tool'; readonly key: string; readonly entry: ToolEntry };

export type Row =
  | { readonly key: string; readonly type: 'user'; readonly message: UserMessage }
  | { readonly key: string; readonly type: 'assistant'; readonly parts: readonly Part[]; readonly streaming: boolean; /** The turn is still running (the last row while a run is active). */ readonly active?: boolean; readonly stopReason?: AssistantMessage['stopReason']; readonly errorMessage?: string; readonly text: string; /** When the reply was written (the last round of a merged turn), in ms. Absent while it streams. */ readonly timestamp?: number; /** The model that wrote the last round of the reply. */ readonly model?: { readonly provider: string; readonly modelId: string }; /** How long the last round took to answer, in ms (Pi's `durationMs`). */ readonly durationMs?: number; /** The native entry of its last committed round: where a fork of the conversation after this reply starts. */ readonly entryId?: string }
  | { readonly key: string; readonly type: 'orphan-result'; readonly message: ToolResultMessage }
  | { readonly key: string; readonly type: 'system'; readonly text: string }
  | { readonly key: string; readonly type: 'event'; readonly label: string }
  | { readonly key: string; readonly type: 'card'; readonly card: ChatCard };

export function object(value: JsonValue | undefined): JsonObject | undefined {
  return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : undefined;
}
export function streamParts(value: JsonValue | undefined): StreamPart[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item): StreamPart[] => {
    const part = object(item);
    if (part?.['type'] === 'text' && typeof part['text'] === 'string') return [{ type: 'text', text: part['text'] }];
    if (part?.['type'] === 'thinking' && typeof part['thinking'] === 'string') return [{ type: 'thinking', thinking: part['thinking'] }];
    const args = object(part?.['arguments']);
    if (part?.['type'] === 'toolCall' && typeof part['id'] === 'string' && typeof part['name'] === 'string' && args) return [{ type: 'toolCall', id: part['id'], name: part['name'], arguments: args }];
    return [];
  });
}

export function queuedMessages(view: ConversationView | undefined): QueuedMessage[] {
  const items = object(view?.docs['pi.inbox'])?.['items'];
  if (!Array.isArray(items)) return [];
  return items.filter((item): item is QueuedMessage => {
    const value = object(item as JsonValue);
    return value !== undefined && (value['mode'] === 'steer' || value['mode'] === 'followUp') && value['id'] !== undefined;
  });
}

export interface Derived {
  readonly rows: readonly Row[];
  /** Required entry and tool cards: pinned above the transcript. */
  readonly pinned: readonly { readonly key: string; readonly content: ReactNode }[];
  readonly run: JsonObject | undefined;
  readonly retry: JsonObject | undefined;
  readonly compacting: boolean;
}
export interface DeriveOptions {
  readonly mode: Mode;
  readonly renderEntry: ((entry: EntryRecord) => ChatCard | undefined) | undefined;
  readonly renderTool: ((call: ToolCall, result: ToolResultMessage | undefined) => ChatCard | undefined) | undefined;
  readonly groupTool: ((call: ToolCall, result: ToolResultMessage) => boolean) | undefined;
  /** Turn artifact tool results into cards (`detect` recognises descriptors the tool result does not carry itself). */
  readonly artifacts?: { readonly detect?: ArtifactsConfig['detect'] | undefined } | undefined;
}

/** Key of `{ summary, decision? }` in a gated call's details: `APPROVAL_DETAILS` of `@hachej/boring-agent/approval` (a contract test keeps them equal). */
export const APPROVAL_DETAILS = 'boring.approval';
export type ApprovalDecision = 'approved' | 'denied' | 'cancelled';
/** The approval record a gated call publishes: its summary and, once made, the decision (`approved`, `denied` or `cancelled`). */
const approvalRecord = (details: unknown): { summary: string; decision?: ApprovalDecision } | undefined => {
  const record = object(object(details as JsonValue | undefined)?.[APPROVAL_DETAILS]);
  const summary = record?.['summary'], decision = record?.['decision'];
  if (typeof summary !== 'string' || !summary.trim()) return undefined;
  return { summary: summary.trim(), ...(decision === 'approved' || decision === 'denied' || decision === 'cancelled' ? { decision } : {}) };
};

const textOf = (message: Message): string => message.role === 'assistant' ? message.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n') : '';

export function derive(view: ConversationView | undefined, options: DeriveOptions): Derived {
  const { mode, renderEntry, renderTool } = options;
  const developer = mode === 'developer';
  const live = object(view?.docs['pi.live']);
  const run = object(live?.['run']), generation = object(live?.['generation']);
  const liveMessage = object(generation?.['message']), retry = object(generation?.['retry']);
  const taskId = run?.['taskId'];

  // Pass 1: match each result to its preceding invocation. Model call IDs may be reused.
  type Item = { readonly key: string; readonly entry: EntryRecord; readonly message?: Message; readonly card?: ChatCard };
  const items: Item[] = [], results = new Map<ToolCall, ToolResultMessage>(), counts = new Map<number, number>(), questionIds = new Map<ToolCall, string>();
  const pendingCalls = new Map<string, ToolCall>();
  for (const entry of view?.entries ?? []) {
    const custom = renderEntry?.(entry);
    const card = custom && (developer || custom.required) ? custom : undefined;
    if (card) items.push({ key: `entry:${entry.id}`, entry, card });
    if (!entry.model?.length) { if (!card && developer) items.push({ key: `entry:${entry.id}`, entry }); continue; }
    for (const [index, message] of entry.model.entries()) {
      if (message.role === 'assistant') for (const part of message.content) if (part.type === 'toolCall') { pendingCalls.set(part.id, part); questionIds.set(part, JSON.stringify([entry.id, part.id])); }
      if (message.role === 'toolResult') {
        const call = pendingCalls.get(message.toolCallId);
        if (call) { results.set(call, message); pendingCalls.delete(message.toolCallId); }
      }
      let key = `entry:${entry.id}:${index}`;
      if (message.role === 'assistant' && entry.byTaskId !== undefined) {
        const ordinal = counts.get(entry.byTaskId) ?? 0; counts.set(entry.byTaskId, ordinal + 1);
        key = `assistant:${entry.byTaskId}:${ordinal}`;
      }
      if (!card) items.push({ key, entry, message });
    }
  }
  const matched = new Set(results.values());

  const pinned: { key: string; content: ReactNode }[] = [];
  for (const item of items) if (item.card?.required) pinned.push({ key: item.key, content: item.card.content });

  const status = (result: ToolResultMessage | undefined): ToolStatus => result ? (result.isError ? 'failed' : 'completed') : run ? 'running' : 'unfinished';
  function toolPart(call: ToolCall, key: string, committed: boolean): Part | undefined {
    const result = results.get(call);
    if (call.name === ASK_USER_TOOL) return { kind: 'question', key, call, result, live: !committed, questionId: questionIds.get(call) };
    // A call gated by `requireApproval` identifies itself: it publishes its summary under APPROVAL_DETAILS before it asks.
    const record = approvalRecord(result ? result.details : (Array.isArray(live?.['tools']) ? live['tools'] : []).map(object).find(slot => slot?.['callId'] === call.id)?.['details']);
    if (record) return { kind: 'approval', key, call, result, live: !committed, questionId: questionIds.get(call), summary: record.summary, ...(record.decision ? { decision: record.decision } : {}), ...(result ? { entry: { key: `${key}:step`, call, result, status: status(result) } } : {}) };
    if (options.artifacts) {
      // A finished call that carries a descriptor becomes a card; a running `present` shows an "opening" card. A failed call stays an ordinary (failed) tool step.
      const artifact = result ? detectArtifact(call, result, options.artifacts.detect) : undefined;
      if (artifact) {
        // A tool whose own result carries the descriptor is replaced by its card; a host-detected card is shown in addition to the step.
        const own = result && detectArtifact(call, result);
        return { kind: 'artifact', key, call, state: 'ready', artifact, title: artifact.title, ...(own ? {} : { entry: { key, call, result, status: status(result) } }) };
      }
      if (!result && run && call.name === PRESENT_TOOL) {
        return { kind: 'artifact', key, call, state: 'presenting', artifact: undefined, title: pendingTitle(call) };
      }
    }
    const custom = committed ? renderTool?.(call, result) : undefined;
    if (custom?.required) { pinned.push({ key, content: custom.content }); return undefined; }
    if (custom && (developer || result?.isError || custom.inline)) return { kind: 'tool', key, entry: { key, call, result, status: status(result), custom: custom.content } };
    // A host that folds only some calls (`groupTool`) keeps the rest as cards, which expert mode hides unless they failed.
    if (!developer && !result?.isError && options.groupTool && !(result && safe(options.groupTool, { key, call, result, status: status(result) }))) return undefined;
    return { kind: 'tool', key, entry: { key, call, result, status: status(result) } };
  }
  function partsOf(content: readonly StreamPart[], rowKey: string, streaming: boolean, committed: boolean): Part[] {
    const parts: Part[] = [];
    for (const [index, part] of content.entries()) {
      if (part.type === 'text') { if (part.text.length) parts.push({ kind: 'text', key: `${rowKey}:text:${index}`, text: part.text }); }
      else if (part.type === 'thinking') { if (developer && part.thinking.length) parts.push({ kind: 'thinking', key: `${rowKey}:thinking:${index}`, text: part.thinking, streaming: streaming && index === content.length - 1 }); }
      else { const made = toolPart(part, `${rowKey}:tool:${index}`, committed); if ((made?.kind === 'artifact' || made?.kind === 'approval') && made.entry) parts.push({ kind: 'tool', key: `${made.key}:step`, entry: made.entry }); if (made) parts.push(made); }
    }
    return parts;
  }

  // Pass 2: rows.
  const rows: Row[] = [];
  for (const item of items) {
    if (item.card) { if (!item.card.required) rows.push({ key: item.key, type: 'card', card: item.card }); continue; }
    const message = item.message;
    if (!message) { if (developer) rows.push({ key: item.key, type: 'event', label: item.entry.kind }); continue; }
    if (message.role === 'system') {
      if (developer) rows.push({ key: item.key, type: 'system', text: typeof message.content === 'string' ? message.content : message.content.map(part => part.text).join('\n') });
    } else if (message.role === 'toolResult') {
      // A result with its call is shown on the call's card. Only an unmatched failure gets its own row.
      if (message.isError && !matched.has(message)) rows.push({ key: item.key, type: 'orphan-result', message });
    } else if (message.role === 'user') rows.push({ key: item.key, type: 'user', message });
    else {
      const parts = partsOf(message.content, item.key, false, true);
      const interrupted = message.stopReason === 'error' || message.stopReason === 'aborted';
      if (parts.length || interrupted) rows.push({ key: item.key, type: 'assistant', parts, streaming: false, stopReason: message.stopReason, ...(message.errorMessage ? { errorMessage: message.errorMessage } : {}), text: textOf(message), ...replyMeta(message), entryId: String(item.entry.id) });
      else {
        // A final round with nothing to show adds no content, but it is still the round that ended the reply: its model, time and entry replace the earlier round's.
        const previous = rows[rows.length - 1];
        if (previous?.type === 'assistant' && !previous.stopReason?.match(/^(error|aborted)$/)) {
          const { timestamp: _t, model: _m, durationMs: _d, ...rest } = previous;
          rows[rows.length - 1] = { ...rest, ...replyMeta(message), entryId: String(item.entry.id) };
        }
      }
    }
  }
  if (typeof taskId === 'number' && liveMessage) {
    const key = `assistant:${taskId}:${counts.get(taskId) ?? 0}`, content = streamParts(liveMessage['content']);
    rows.push({ key, type: 'assistant', parts: partsOf(content, key, true, false), streaming: true, text: '' });
  }
  const merged = mergeTurns(rows).map(row => row.type === 'assistant' && options.artifacts ? { ...row, parts: oneCardPerArtifact(row.parts) } : row);
  const last = merged[merged.length - 1];
  if (run && last?.type === 'assistant') merged[merged.length - 1] = { ...last, active: true };
  return { rows: merged, pinned, run, retry, compacting: Array.isArray(live?.['compactions']) && live['compactions'].length > 0 };
}

/** What a reply reports about the model round that wrote it, read from Pi's own message (each field only when it is there). */
export function replyMeta(message: AssistantMessage): { readonly timestamp?: number; readonly model?: { readonly provider: string; readonly modelId: string }; readonly durationMs?: number } {
  return {
    ...(typeof message.timestamp === 'number' ? { timestamp: message.timestamp } : {}),
    ...(typeof message.provider === 'string' && typeof message.model === 'string' ? { model: { provider: message.provider, modelId: message.model } } : {}),
    ...(typeof message.durationMs === 'number' ? { durationMs: message.durationMs } : {}),
  };
}

/**
 * Pi commits one assistant message per model round, so a turn with tool use is several messages in a row.
 * They read as one answer: merge consecutive assistant rows (unless one ended in an error or stop) so tool calls
 * group across rounds and the turn has a single copy action. The first row's key is kept, so identity is stable.
 */
function mergeTurns(rows: readonly Row[]): Row[] {
  const out: Row[] = [];
  for (const row of rows) {
    const last = out[out.length - 1];
    if (last?.type === 'assistant' && row.type === 'assistant' && !last.stopReason?.match(/^(error|aborted)$/)) {
      out[out.length - 1] = { key: last.key, type: 'assistant', parts: [...last.parts, ...row.parts], streaming: row.streaming,
        ...(row.stopReason ? { stopReason: row.stopReason } : {}), ...(row.errorMessage ? { errorMessage: row.errorMessage } : {}),
        text: [last.text, row.text].filter(Boolean).join('\n\n'), ...(row.timestamp !== undefined ? { timestamp: row.timestamp } : {}), ...(row.model ? { model: row.model } : {}), ...(row.durationMs !== undefined ? { durationMs: row.durationMs } : {}),
        ...(row.entryId !== undefined ? { entryId: row.entryId } : last.entryId !== undefined ? { entryId: last.entryId } : {}) };
    } else out.push(row);
  }
  return out;
}

/**
 * A turn that revises an artifact several times shows one card for it: the last version, at the place of the last step.
 * A running `present` of a file already shown takes over the title of its card.
 */
function oneCardPerArtifact(parts: readonly Part[]): Part[] {
  const idOf = (part: Part) => part.kind === 'artifact' ? part.artifact ? artifactKey(part.artifact) : (part.state === 'presenting' ? pendingId(part.call) : undefined) : undefined;
  const last = new Map<string, number>();
  for (const [index, part] of parts.entries()) { const id = idOf(part); if (id !== undefined) last.set(id, index); }
  const out: Part[] = [];
  for (const [index, part] of parts.entries()) {
    const id = idOf(part);
    if (id === undefined || last.get(id) === index) {
      if (part.kind === 'artifact' && part.artifact === undefined && part.title === undefined && id !== undefined) {
        const earlier = parts.find(other => other.kind === 'artifact' && other.artifact !== undefined && artifactKey(other.artifact) === id);
        if (earlier?.kind === 'artifact') { out.push({ ...part, title: earlier.title }); continue; }
      }
      out.push(part);
    }
  }
  return out;
}

/** One step of an activity block: a default tool call or a stretch of reasoning. */
export type Step = { readonly kind: 'tool'; readonly key: string; readonly entry: ToolEntry }
  | { readonly kind: 'thinking'; readonly key: string; readonly text: string; readonly streaming: boolean };
/** An assistant turn is text parts and activity blocks: one block per uninterrupted run of steps. */
export type Segment = { readonly kind: 'part'; readonly part: Part } | { readonly kind: 'activity'; readonly key: string; readonly steps: readonly Step[] };
export function segments(parts: readonly Part[], groupTool: DeriveOptions['groupTool']): Segment[] {
  const out: Segment[] = [];
  let run: Step[] = [];
  const flush = () => {
    const first = run[0];
    if (first) out.push({ kind: 'activity', key: `activity:${first.key}`, steps: run });
    run = [];
  };
  for (const part of parts) {
    if (part.kind === 'thinking') run.push({ kind: 'thinking', key: part.key, text: part.text, streaming: part.streaming });
    else if (part.kind === 'tool' && !part.entry.custom && (!groupTool || safe(groupTool, part.entry))) run.push({ kind: 'tool', key: part.key, entry: part.entry });
    else { flush(); out.push({ kind: 'part', part }); }
  }
  flush();
  return out;
}
function safe(groupTool: NonNullable<DeriveOptions['groupTool']>, entry: ToolEntry): boolean {
  try { return entry.result !== undefined && !entry.result.isError && groupTool(entry.call, entry.result) === true; } catch { return false; }
}

'use client';

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { KeyboardEvent, ReactNode } from 'react';
import type { EntryRecord } from '@earendil-works/pi-durable';
import type { ImageContent, ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import type { ChatAttachment, NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { useStickToBottom } from 'use-stick-to-bottom';
import type { ComposerFeedback, PendingUpload } from './composer';
import type { AttachmentsConfig, EffortConfig, MentionsConfig, ModelConfig, ModelRef, PastedText, PasteToFile, SlashConfig } from './config';
import { looksLikeMarkdown, mentionToken } from './config';
import { ModelEffortPicker } from './pickers';
import type { CommandMentions } from './markdown';
import type { RowContext } from './message';
import type { QueueActions, QueuedMessage } from './queue';
import type { AnswerOutcome } from './question-card';
import type { ArtifactsConfig } from './artifact';
import { derive, isFileBlock, object, queuedMessages } from './rows';
import type { ChatCard, Mode } from './rows';
import { useChatText } from './labels';
import type { BlockAction } from '../button/actions';
import type { ReplyRef } from './config';

/** What the host lets the person do beyond typing. Pass `remote.answer` and `remote.withdraw` from `createRemoteChat()`. */
export interface PiChatActions {
  /** Resolve a pending `ask_user` question. Without it, question cards are read-only. */
  readonly answer?: (questionId: string, answer: string) => Promise<AnswerOutcome>;
  /** Withdraw a queued message before Pi places it. Without it, queued messages cannot be cancelled. */
  readonly withdraw?: (id: QueuedMessage['id']) => Promise<unknown>;
}

/** The props `PiChat` and `AmbientChat` both take and hand to `useChatSession`. */
export interface ChatFeatureProps {
  /** `expert` hides successful tool details and reasoning; `developer` shows everything. */
  readonly mode?: Mode;
  readonly actions?: PiChatActions;
  readonly renderEntry?: (entry: EntryRecord) => ChatCard | undefined;
  readonly renderTool?: (call: ToolCall, result: ToolResultMessage | undefined) => ChatCard | undefined;
  readonly groupTool?: (call: ToolCall, result: ToolResultMessage) => boolean;
  readonly commandMentions?: CommandMentions;
  readonly onOpenImage?: (image: ImageContent) => void;
  readonly onCopy?: (text: string) => Promise<void>;
  readonly onComposerKeyDown?: (event: KeyboardEvent<HTMLTextAreaElement>) => void;
  readonly fileAccept?: string;
  /** `/` menu of host commands and skills. Omit it and `/` is just text. */
  readonly slash?: SlashConfig;
  /** Opens an `uploads/` file from its card in a sent message. Without it the card is not clickable. */
  readonly onOpenFile?: (path: string) => void;
  /** Pastes above these limits become a file through `attachments` (on by default, 2000 characters or 40 lines). Needs `attachments`. */
  readonly pasteToFile?: PasteToFile;
  /** `@` workspace file mentions: a picker, composer chips and styled mentions in sent messages. */
  readonly mentions?: MentionsConfig;
  /** Attach button, paste and drop through the host's upload. Takes the place of `onFiles` and `fileAccept`. */
  readonly attachments?: AttachmentsConfig;
  /** Model picker in the composer bar. The current model comes from the view's `pi.agent` document. */
  readonly model?: ModelConfig;
  /** Thinking level picker in the composer bar. The current level comes from the view's `pi.agent` document. */
  readonly effort?: EffortConfig;
  /** Artifact cards: tool results that carry a descriptor become a card that opens the artifact in the host's panel. Omit it and nothing changes. */
  readonly artifacts?: ArtifactsConfig;
  /**
   * Host actions under each settled reply, beside Copy (and Fork): `header` ones as buttons, `menu` ones in a "…" menu. Test ids
   * `reply-action-<id>`, the menu `reply-action-more`.
   */
  readonly messageActions?: ((reply: ReplyRef) => readonly BlockAction[]) | undefined;
  /** A line under each settled reply (for example the model that answered and the time it took), for the host to show to some people only. */
  readonly replyFooter?: ((reply: ReplyRef) => ReactNode) | undefined;
}


export type FilesHandler = (files: readonly File[], target: Pick<ReturnType<NativeChatController['getSnapshot']>, 'identity' | 'conversationId'> & { readonly signal: AbortSignal }) => Promise<readonly ChatAttachment[]>;

/** The chat behaviour every surface over a `NativeChatController` shares (`PiChat`, `AmbientChat`): sending, queue actions, uploads, pickers, rows. */
export interface ChatSessionOptions extends Readonly<{ [Key in keyof ChatFeatureProps]: ChatFeatureProps[Key] | undefined }> {
  readonly controller: NativeChatController;
  /** The controller the host currently passes; a surface that outlives its controller stops acting on the old one. */
  readonly activeController: { readonly current: NativeChatController };
  readonly mode: Mode;
  readonly fileAccept: string;
  readonly onFiles?: FilesHandler | undefined;
  /** Runs after a message was accepted for sending (for example to scroll to the bottom). */
  readonly afterSend?: (() => void) | undefined;
  /** Extra attributes of the row context a surface needs (for example per-reply actions). */
  readonly rowExtras?: Partial<RowContext> | undefined;
  /** The optional annotate toggle: when notes are pending (`count` > 0), Send attaches them to the message first. */
  readonly feedback?: ComposerFeedback | undefined;
}

export function useChatSession(options: ChatSessionOptions) {
  const { controller, activeController: active, mode, actions, renderEntry, renderTool, groupTool, commandMentions, onOpenImage, onCopy, onComposerKeyDown, onFiles, fileAccept,
    slash, mentions, attachments, model, effort, artifacts, messageActions, replyFooter, afterSend, rowExtras, feedback, onOpenFile, pasteToFile } = options;
  const { labels } = useChatText();
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(0);
  const [picked, setPicked] = useState<readonly string[]>([]);
  const [pending, setPending] = useState<readonly PendingUpload[]>([]);
  const [changing, setChanging] = useState<'model' | 'effort' | null>(null);
  const [changeError, setChangeError] = useState<string | null>(null);
  const [optimistic, setOptimistic] = useState<{ readonly model?: ModelRef; readonly effort?: string }>({});
  const uploadIds = useRef(0);
  const uploads = useRef(new Set<AbortController>()), mounted = useRef(false);
  const textarea = useRef<HTMLTextAreaElement | null>(null);
  const current = () => mounted.current && active.current === controller && !controller.getSnapshot().disposed;
  useEffect(() => {
    mounted.current = true;
    // A controller disposed before mount throws synchronously; the chat then renders its disposed state.
    if (!controller.getSnapshot().disposed) void controller.connect().catch(cause => { if (current()) setError(cause instanceof Error ? cause.message : labels.connectionFailed); });
    return () => { mounted.current = false; for (const upload of uploads.current) upload.abort(); uploads.current.clear(); };
  }, [controller]);

  const developer = mode === 'developer';
  // Only the recogniser takes part in deriving rows; which card is open changes without rebuilding them.
  const artifactDetect = useMemo(() => artifacts ? { detect: artifacts.detect } : undefined, [Boolean(artifacts), artifacts?.detect]); // eslint-disable-line react-hooks/exhaustive-deps
  const derived = useMemo(() => derive(state.view, { mode, renderEntry, renderTool, groupTool, artifacts: artifactDetect }), [state.view, mode, renderEntry, renderTool, groupTool, artifactDetect]);
  const queued = useMemo(() => queuedMessages(state.view), [state.view]);
  const { rows, run } = derived;

  const report = (cause: unknown) => { if (current()) setError(cause instanceof Error ? cause.message : labels.actionFailedShort); };
  const act = (action: () => Promise<unknown>) => {
    setError(null);
    try { void action().catch(report); } catch (cause) { report(cause); }
  };
  // A send being confirmed does not block the next one: the controller empties the composer at once and queues the next message behind it.
  // Only a submission whose outcome is unknown blocks, until it is checked or retried.
  const unconfirmed = state.send.kind === 'unknown';
  const connected = state.connection.kind === 'connected';
  const sendBlocked = uploading > 0 || state.disposed || !connected || unconfirmed;
  /** Puts a message back into the composer ahead of whatever is there now (nothing is dropped). */
  const putBack = (text: string, images: readonly ChatAttachment[]) => {
    if (controller.getSnapshot().disposed) return;
    const draft = controller.getSnapshot().draft;
    controller.setText([text, draft.text].filter(value => value.trim()).join('\n'));
    if (images.length) controller.setAttachments([...images, ...draft.attachments.filter(item => !images.some(image => image.id === item.id))]);
  };
  const working = Boolean(run);
  const waitingForAnswer = rows.some(row => row.type === 'assistant' && row.parts.some(part => (part.kind === 'question' || part.kind === 'approval') && !part.live && !part.result));
  const send = () => {
    if (sendBlocked || !current()) return;
    const attach = feedback && feedback.count > 0 ? feedback.attach : undefined;
    if (attach) {
      // The pending feedback goes with this message: the host attaches it to the text, then the native send reads the draft.
      act(async () => {
        // Like any send, the composer empties at once; the person's own text comes back if the feedback or the message is refused.
        const typed = controller.getSnapshot().draft;
        controller.setText(''); controller.setAttachments([]);
        let attached: Awaited<ReturnType<typeof attach>>;
        try { attached = await attach(typed.text); }
        catch (cause) { putBack(typed.text, typed.attachments); throw cause; }
        if (attached.kind === 'refused') { putBack(typed.text, typed.attachments); throw new Error(attached.reason); }
        if (!current()) { putBack(typed.text, typed.attachments); return; }
        const submission = await controller.send('followUp', { text: attached.text, attachments: typed.attachments, restore: { text: typed.text, attachments: typed.attachments } });
        if (submission) feedback?.sent();
      });
      afterSend?.();
      textarea.current?.focus();
      return;
    }
    act(() => controller.send('followUp'));
    afterSend?.();
    textarea.current?.focus();
  };
  // A queued message is taken back (withdrawn) before it is edited or steered; if Pi already placed it, that is reported and nothing is lost.
  async function takeBack(item: QueuedMessage) {
    if (!actions?.withdraw) throw new Error(labels.queueLocked);
    const outcome = await actions.withdraw(item.id);
    if (outcome === 'already_placed' || outcome === 'settled') throw new Error(labels.tooLate);
  }
  const queuedContent = (item: QueuedMessage) => {
    const parts = Array.isArray(item.content) ? item.content as readonly { type?: unknown; text?: unknown; data?: unknown; mimeType?: unknown }[] : [];
    const text = typeof item.content === 'string' ? item.content : parts.flatMap(part => part?.type === 'text' && typeof part.text === 'string' && !isFileBlock(part.text) ? [part.text] : []).join('\n');
    const images: ChatAttachment[] = parts.flatMap((part, index) => part?.type === 'image' && typeof part.data === 'string' && typeof part.mimeType === 'string'
      ? [{ id: `queued-${String(item.id)}-${index}`, name: `image-${index + 1}`, content: { type: 'image' as const, data: part.data, mimeType: part.mimeType } }] : []);
    return { text, images };
  };
  const queueActions: QueueActions | undefined = actions?.withdraw ? {
    edit: async item => {
      await takeBack(item);
      const { text, images } = queuedContent(item), draft = controller.getSnapshot().draft;
      controller.setText(draft.text.trim() ? `${text}\n${draft.text}` : text);
      if (images.length) controller.setAttachments([...draft.attachments, ...images]);
      textarea.current?.focus();
    },
    steer: async item => {
      if (sendBlocked) throw new Error(labels.waitToSteer);
      await takeBack(item);
      const { text, images } = queuedContent(item);
      // Sent as explicit content, so the person's own draft is never touched; a refused steer comes back into the composer (the controller
      // puts it back), an unknown one is held for checking.
      try {
        const submission = await controller.send('steer', { text, attachments: images });
        if (!submission && current() && controller.getSnapshot().send.kind === 'blocked') setError(labels.steerRefused);
      } catch (cause) { putBack(text, images); if (current()) setError(cause instanceof Error ? cause.message : labels.steerFailed); }
    },
  } : undefined;
  const addMentions = (paths: readonly string[]) => {
    const text = controller.getSnapshot().draft.text;
    controller.setText(`${text}${text && !/\s$/.test(text) ? ' ' : ''}${paths.map(mentionToken).join(' ')} `);
    setPicked(value => [...new Set([...value, ...paths])]);
  };
  /** Uploads files; `restore` (a pasted text) is what their pending cards undo: it abandons the upload and puts the text back. */
  async function upload(files: readonly File[], paste?: { readonly restore: () => void; readonly after: string }) {
    if ((!onFiles && !attachments) || !files.length || !current()) return;
    const abort = new AbortController(); uploads.current.add(abort); setUploading(value => value + 1);
    const ids = files.map(() => `upload-${++uploadIds.current}`);
    const settle = (failure?: string) => setPending(items => failure === undefined ? items.filter(item => !ids.includes(item.id))
      : items.map(item => ids.includes(item.id) ? { ...item, state: 'failed', error: failure } : item));
    const cancel = paste && (() => { abort.abort(); setPending(items => items.filter(item => !ids.includes(item.id))); paste.restore(); });
    setPending(items => [...items, ...files.map((file, index): PendingUpload => ({ id: ids[index]!, name: file.name, state: 'uploading',
      ...(cancel && paste ? { cancel, restoreWhile: paste.after } : {}) }))]);
    try {
      let added: readonly ChatAttachment[] = [];
      let paths: string[] = [];
      if (attachments) {
        for (const result of await attachments.upload([...files], abort.signal)) {
          if (result.image) added = [...added, { id: `image-${Date.now()}-${++uploadIds.current}`, name: result.name, content: { type: 'image', data: result.image.data, mimeType: result.image.mimeType } }];
          else if (result.path) paths = [...paths, result.path];
        }
      } else added = await onFiles!(files, { identity: state.identity, conversationId: state.conversationId, signal: abort.signal });
      if (current() && !abort.signal.aborted) {
        if (added.length) controller.setAttachments([...controller.getSnapshot().draft.attachments, ...added]);
        if (paths.length) addMentions(paths);
        settle();
      }
    } catch (cause) { if (!abort.signal.aborted) { settle(cause instanceof Error ? cause.message : labels.uploadFailedShort); if (!attachments) report(cause); } }
    finally { uploads.current.delete(abort); if (current()) setUploading(value => value - 1); }
  }
  /** A paste the composer took: saved as a file under `uploads/` (Send then references it). Cancelling puts the text back where it was pasted. */
  const pasteText = (paste: PastedText) => {
    if (!attachments || !current()) return;
    const at = new Date(), two = (value: number) => String(value).padStart(2, '0');
    const stamp = `${at.getFullYear()}-${two(at.getMonth() + 1)}-${two(at.getDate())} ${two(at.getHours())}-${two(at.getMinutes())}-${two(at.getSeconds())}`;
    const markdown = looksLikeMarkdown(paste.text);
    const file = new File([paste.text], `${labels.pastedFileName(stamp)}${markdown ? '.md' : '.txt'}`, { type: markdown ? 'text/markdown' : 'text/plain' });
    // The pasted text replaces its selection when the paste is accepted, so the draft shows what is left. Restoring inserts the text at
    // the same place and deletes nothing: whatever was typed since stays.
    const draft = controller.getSnapshot().draft.text;
    const start = Math.min(paste.start, draft.length), end = Math.min(Math.max(paste.end, start), draft.length);
    const after = `${draft.slice(0, start)}${draft.slice(end)}`;
    controller.setText(after);
    const restore = () => {
      if (!current()) return;
      const now = controller.getSnapshot().draft.text;
      const at = Math.min(start, now.length);
      controller.setText(`${now.slice(0, at)}${paste.text}${now.slice(at)}`);
      textarea.current?.focus();
    };
    void upload([file], { restore, after });
  };
  const agentDoc = object(state.view?.docs['pi.agent']);
  const currentModel = object(agentDoc?.['model']);
  const viewModel: ModelRef | undefined = typeof currentModel?.['provider'] === 'string' && typeof currentModel['modelId'] === 'string' ? { provider: currentModel['provider'], modelId: currentModel['modelId'] } : undefined;
  const viewEffort = typeof agentDoc?.['thinkingLevel'] === 'string' ? agentDoc['thinkingLevel'] : undefined;
  // Show the accepted choice until the watch delivers it, so the label does not flicker back.
  useEffect(() => {
    const same = optimistic.model && viewModel && optimistic.model.provider === viewModel.provider && optimistic.model.modelId === viewModel.modelId;
    if (same || (optimistic.effort !== undefined && optimistic.effort === viewEffort)) setOptimistic(value => ({ ...(same ? {} : value.model ? { model: value.model } : {}), ...(optimistic.effort === viewEffort ? {} : value.effort ? { effort: value.effort } : {}) }));
  }, [optimistic, viewModel?.provider, viewModel?.modelId, viewEffort]);
  useEffect(() => { if (!state.draft.text) setPicked(value => value.length ? [] : value); }, [state.draft.text]);
  async function change(kind: 'model' | 'effort', apply: () => Promise<void>, accepted: () => void, rejected: () => void) {
    if (changing || !current()) return;
    setChanging(kind); setChangeError(null);
    try { await apply(); if (current()) accepted(); }
    catch (cause) { if (current()) { rejected(); setChangeError(cause instanceof Error && cause.message ? cause.message : labels.changeRefused); } }
    finally { if (current()) setChanging(null); }
  }
  const activateMention = (command: { readonly name: string; readonly behavior: 'execute' | 'insert' }) => {
    if (!current() || controller.getSnapshot().connection.kind !== 'connected') return;
    const catalog = commandMentions;
    const selected = catalog?.commands.find(item => item.name === command.name && item.behavior === command.behavior);
    if (catalog && selected) act(async () => catalog.onActivate({ name: selected.name, behavior: selected.behavior }));
  };
  const rowContext = useMemo<RowContext>(() => ({
    developer, groupTool, onOpenImage, onCopy, openFile: onOpenFile,
    commandMentions: commandMentions ? { commands: commandMentions.commands, onActivate: activateMention } : undefined,
    answer: actions?.answer,
    artifacts: artifacts ? { open: artifacts.open, isOpen: artifacts.isOpen } : undefined,
    messageActions,
    replyFooter,
    pieces: slash?.skills?.length || mentions || attachments ? { mentions: Boolean(mentions), uploads: Boolean(attachments), skills: (slash?.skills ?? []).map(skill => skill.name), openMention: mentions?.open, renderMention: mentions?.render, preview: mentions?.preview } : undefined,
    ...rowExtras,
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [developer, groupTool, onOpenImage, onCopy, onOpenFile, commandMentions, actions?.answer, slash?.skills, mentions, mentions?.open, mentions?.render, mentions?.preview, attachments, artifacts?.open, artifacts?.isOpen, messageActions, replyFooter, rowExtras]);

  /** The model-and-effort pill and the note that reports a refused change. */
  const pickers = () => {
    const disabled = changing !== null || state.disposed || !connected;
    const barStart = model || effort ? <ModelEffortPicker model={model} effort={effort} currentModel={optimistic.model ?? viewModel} currentEffort={optimistic.effort ?? viewEffort} disabled={disabled} busy={changing}
      onModel={next => void change('model', () => model!.change(next), () => setOptimistic(value => ({ ...value, model: next })), () => {})}
      onEffort={next => void change('effort', () => effort!.change(next), () => setOptimistic(value => ({ ...value, effort: next })), () => {})} /> : undefined;
    const barNote = changeError ? <button type="button" role="alert" data-testid="configure-error" title={`${changeError} (${labels.dismissHint})`} onClick={() => setChangeError(null)}
      className="min-w-0 max-w-[16rem] cursor-pointer truncate rounded-md bg-destructive/10 px-2 py-1 text-xs text-destructive outline-none focus-visible:ring-2 focus-visible:ring-ring/60">{changeError}</button> : undefined;
    return { barStart, barNote };
  };

  const empty = connected && !state.view?.entries.length && !rows.length;
  const loading = (state.connection.kind === 'idle' || state.connection.kind === 'connecting') && !state.view;

  /** Everything `Composer` needs from the session; a surface adds its layout and slots. */
  const composer = {
    text: state.draft.text, onText: (text: string) => controller.setText(text), onKeyDown: onComposerKeyDown, textareaRef: textarea,
    attachments: state.draft.attachments.map(item => ({ id: item.id, name: item.name, mimeType: item.content.mimeType, data: item.content.data })),
    onRemoveAttachment: (id: string) => controller.setAttachments(controller.getSnapshot().draft.attachments.filter(item => item.id !== id)),
    working, sendBlocked, disabled: state.disposed, stopRequested: state.stop === 'requested',
    onSend: send, onStop: () => act(controller.stop),
    uploading: uploading > 0, canAttach: Boolean(onFiles || attachments), fileAccept: attachments ? attachments.accept ?? '' : fileAccept, onPickFiles: (files: readonly File[]) => { void upload(files); },
    slash, onSlashError: report, mentions, mentionPaths: picked, onMentionPicked: (path: string) => setPicked(value => value.includes(path) ? value : [...value, path]),
    uploads: pending, onDismissUpload: (id: string) => setPending(items => items.filter(item => item.id !== id)),
    onPasteText: attachments ? pasteText : undefined, pasteToFile,
    feedback,
  };

  return { state, derived, rows, queued, queueActions, working, waitingForAnswer, connected, sendBlocked, error, setError, report, act, current, textarea, rowContext, composer, pickers, empty, loading, developer };
}

export type ChatSession = ReturnType<typeof useChatSession>;

/** Scroll-to-bottom transcript with older rows revealed in pages as the person scrolls up. */
export function useTranscript(rows: readonly unknown[], page = 60, more = 40) {
  const [limit, setLimit] = useState(page);
  const anchor = useRef<{ readonly height: number; readonly top: number } | undefined>(undefined);
  // Growth re-pins at once: a spring trails the rows that grow after insert (streamed text, late images) and leaves the newest one under the composer.
  const library = useStickToBottom({ initial: 'instant', resize: 'instant' });
  // The scroller can mount later (AmbientChat starts collapsed) and unmount on collapse, so the element is held in state.
  const [scroller, setScroller] = useState<HTMLElement | null>(null);
  const scrollRef = useCallback((element: HTMLElement | null) => { library.scrollRef(element); setScroller(element); }, [library.scrollRef]);
  const stick = { ...library, scrollRef };
  // The library observes only the content. A shorter viewport (phone keyboard, a taller composer) leaves the newest row below the fold,
  // so re-pin when the viewport shrinks while the reader is at the bottom.
  useEffect(() => {
    if (!scroller || typeof ResizeObserver === 'undefined') return;
    let height = scroller.clientHeight;
    const observer = new ResizeObserver(() => {
      const shrank = scroller.clientHeight < height;
      height = scroller.clientHeight;
      if (shrank && library.state.isAtBottom) void library.scrollToBottom('instant');
    });
    observer.observe(scroller);
    return () => observer.disconnect();
  }, [scroller, library.state, library.scrollToBottom]);
  // The library ignores scroll events while it is absorbing a growth (a resize difference), so a scroll-up in that window would be
  // snapped back by its pending frame. Release the bottom lock as soon as the reader moves up. The library's own programmatic
  // writes are marked in ignoreScrollToTop, which its listener clears: this listener is a capture listener so it reads the mark first.
  useEffect(() => {
    if (!scroller) return;
    let last = scroller.scrollTop;
    const onScroll = () => {
      const top = scroller.scrollTop;
      const programmatic = library.state.ignoreScrollToTop === top;
      if (!programmatic && top < last && !library.state.isNearBottom && library.state.isAtBottom) library.stopScroll();
      last = top;
    };
    scroller.addEventListener('scroll', onScroll, { passive: true, capture: true });
    return () => scroller.removeEventListener('scroll', onScroll, { capture: true });
  }, [scroller, library.state, library.stopScroll]);
  const hidden = Math.max(0, rows.length - limit);
  // Reveal older rows when the person scrolls near the top, keeping the same rows in view.
  const reveal = useCallback(() => {
    if (scroller) anchor.current = { height: scroller.scrollHeight, top: scroller.scrollTop };
    setLimit(value => value + more);
  }, [scroller, more]);
  useLayoutEffect(() => {
    const saved = anchor.current;
    if (scroller && saved) { scroller.scrollTop = saved.top + scroller.scrollHeight - saved.height; anchor.current = undefined; }
  }, [limit, scroller]);
  useEffect(() => {
    if (!scroller) return;
    const onScroll = () => { if (scroller.scrollTop < 240 && scroller.scrollHeight > scroller.clientHeight && hidden > 0 && !anchor.current) reveal(); };
    scroller.addEventListener('scroll', onScroll, { passive: true });
    return () => scroller.removeEventListener('scroll', onScroll);
  }, [hidden, reveal, scroller]);
  return { stick, hidden, reveal, visible: <T,>(items: readonly T[]): readonly T[] => hidden ? items.slice(hidden) : items, reset: () => setLimit(page) };
}

import type { ElementType, ReactNode } from 'react';
import { cn } from '../utils/utils';

/** Text with a moving highlight while `active` (styles: `.pi-chat-shimmer` in this item's css). Plain text otherwise. */
export function Shimmer({ children, active = true, as: Tag = 'span', className }: { readonly children: ReactNode; readonly active?: boolean; readonly as?: ElementType; readonly className?: string }) {
  return <Tag className={cn(active && 'pi-chat-shimmer motion-reduce:animate-none', className)}>{children}</Tag>;
}

'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import { usePickerKeyboard } from './picker-keyboard';
import { slashGroup } from './config';
import type { SlashItem } from './config';
import { cn } from '../utils/utils';
import { useChatText } from './labels';

const ALL = '__all__';

/**
 * The `/` menu, ported from v2's `SlashCommandPicker`: a search box seeded from what was typed after `/`, filter chips
 * (All, built-in, skills, plugin names), then rows with a name, badges and a one line description.
 */
export function SlashMenu({ query, items, onSelect, onDismiss }: {
  readonly query: string;
  readonly items: readonly SlashItem[];
  readonly onSelect: (item: SlashItem) => void;
  readonly onDismiss: () => void;
}) {
  const { labels } = useChatText();
  const [group, setGroup] = useState(ALL);
  const [search, setSearch] = useState(query);
  const [active, setActive] = useState(0);
  const container = useRef<HTMLDivElement>(null), list = useRef<HTMLUListElement>(null);
  // Follow the composer text.
  useEffect(() => { setSearch(query); setActive(0); }, [query]);
  const groups = useMemo(() => [...new Set(items.map(slashGroup))].sort((a, b) => a.localeCompare(b)), [items]);
  const filtered = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return items.filter(item => (group === ALL || slashGroup(item) === group)
      && (!needle || item.name.toLowerCase().includes(needle) || item.description.toLowerCase().includes(needle)));
  }, [items, search, group]);
  useEffect(() => { setActive(index => filtered.length === 0 ? 0 : Math.min(index, filtered.length - 1)); }, [filtered.length]);
  useEffect(() => {
    const outside = (event: MouseEvent) => { if (container.current && !container.current.contains(event.target as Node)) onDismiss(); };
    document.addEventListener('mousedown', outside);
    return () => document.removeEventListener('mousedown', outside);
  }, [onDismiss]);
  usePickerKeyboard({ count: filtered.length, activeIdx: active, setActiveIdx: setActive, listRef: list, onSelect: index => { const item = filtered[index]; if (item) onSelect(item); }, onDismiss });

  const optionId = (index: number) => `pi-chat-slash-${index}`;
  return <div ref={container} data-testid="slash-menu" className="absolute inset-x-0 bottom-full z-20 mb-2 overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground shadow-lg">
    <input aria-label={labels.searchCommands} data-testid="slash-search" type="text" autoComplete="off" spellCheck={false} value={search}
      onChange={event => { setSearch(event.currentTarget.value); setActive(0); }}
      className="block w-full border-0 border-b border-border/60 bg-transparent px-3 py-2 text-base outline-none placeholder:text-muted-foreground sm:text-xs max-sm:min-h-11" placeholder={labels.searchCommands} />
    <div role="tablist" aria-label={labels.filterBySource} className="flex flex-wrap gap-1 border-b border-border/60 px-2 py-1.5">
      {[ALL, ...groups].map(name => <button key={name} type="button" role="tab" aria-selected={group === name} data-testid="slash-chip" data-group={name === ALL ? 'all' : name}
        onMouseDown={event => { event.preventDefault(); setGroup(name); setActive(0); }}
        className={cn('cursor-pointer rounded-full px-2 py-px text-xs font-medium transition-colors max-sm:min-h-10 max-sm:min-w-10 max-sm:px-3 pointer-coarse:min-h-10 pointer-coarse:min-w-10 motion-reduce:transition-none',
          group === name ? 'bg-foreground/10 text-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/70')}>{name === ALL ? labels.allSources : labels.slashGroup(name)}</button>)}
    </div>
    {filtered.length === 0
      ? <div data-testid="slash-empty" className="px-3 py-2 text-xs text-muted-foreground">{labels.noCommands}</div>
      : <ul ref={list} role="listbox" aria-label={labels.commands} className="m-0 max-h-[min(20rem,45dvh)] list-none overflow-y-auto p-0 py-1">
        {filtered.map((item, index) => <li key={`${item.source}:${item.name}`} id={optionId(index)} role="option" aria-selected={index === active} title={item.description || undefined}
          data-testid="slash-item" data-name={item.name} data-source={item.source} data-active={index === active ? 'true' : undefined}
          onMouseEnter={() => setActive(index)} onMouseDown={event => { event.preventDefault(); onSelect(item); }}
          className={cn('flex cursor-pointer flex-col gap-0.5 px-3 py-1.5 text-xs max-sm:min-h-11 max-sm:justify-center pointer-coarse:min-h-11 pointer-coarse:justify-center', index === active ? 'bg-accent text-foreground' : 'text-muted-foreground')}>
          <span className="flex items-center gap-1.5">
            <span className="font-medium text-foreground">/{item.name}</span>
            {item.source === 'skill' && <span data-testid="slash-badge-skill" className="rounded-sm bg-primary/10 px-1 py-px text-xs font-semibold tracking-wide text-foreground uppercase">{labels.skillBadge}</span>}
            {item.sourcePlugin && <span data-testid="slash-badge-source" className="rounded-sm bg-muted px-1 py-px text-xs font-medium text-muted-foreground">{item.sourcePlugin}</span>}
          </span>
          {item.description && <span className="truncate text-xs opacity-70">{item.description}</span>}
        </li>)}
      </ul>}
  </div>;
}

'use client';

import { useState } from 'react';
import type { ReactNode } from 'react';
import type { ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import { AlertCircleIcon, CheckCircle2Icon, ChevronDownIcon, CircleDashedIcon, Loader2Icon, WrenchIcon } from 'lucide-react';
import { cn } from '../utils/utils';
import { defaultChatLabels, useChatText } from './labels';
import type { ChatLabels } from './labels';

export type ToolStatus = 'running' | 'completed' | 'failed' | 'unfinished';
export interface ToolEntry { readonly key: string; readonly call: ToolCall; readonly result: ToolResultMessage | undefined; readonly status: ToolStatus; readonly custom?: ReactNode }

const STATUS_LABEL = { running: 'toolRunning', completed: 'toolCompleted', failed: 'toolFailedStatus', unfinished: 'toolUnfinished' } as const satisfies Record<ToolStatus, keyof ChatLabels>;
const PREVIEW_KEYS = ['path', 'file_path', 'filePath', 'command', 'query', 'pattern', 'name', 'url', 'id'];

/** A short hint of what the call acts on, shown next to its name. */
export function preview(args: ToolCall['arguments']): string {
  const values = args as Record<string, unknown>;
  for (const key of PREVIEW_KEYS) { const value = values[key]; if (typeof value === 'string' && value) return value.replace(/\s+/g, ' ').slice(0, 90); }
  const first = Object.values(values).find(value => typeof value === 'string' && value);
  return typeof first === 'string' ? first.replace(/\s+/g, ' ').slice(0, 90) : '';
}

export function StatusIcon({ status, className }: { readonly status: ToolStatus; readonly className?: string }) {
  const cls = cn('size-4 shrink-0', className);
  if (status === 'running') return <Loader2Icon aria-hidden="true" className={cn(cls, 'animate-spin text-muted-foreground motion-reduce:animate-none')} />;
  if (status === 'completed') return <CheckCircle2Icon aria-hidden="true" className={cn(cls, 'text-(--chat-success)')} />;
  if (status === 'failed') return <AlertCircleIcon aria-hidden="true" className={cn(cls, 'text-destructive')} />;
  return <CircleDashedIcon aria-hidden="true" className={cn(cls, 'text-muted-foreground')} />;
}

function Section({ title, children }: { readonly title: string; readonly children: ReactNode }) {
  return <div className="space-y-1.5"><h4 className="m-0 text-xs font-medium tracking-wider text-muted-foreground uppercase">{title}</h4>{children}</div>;
}

/** A short live label for a call: "Reading notes/consultation.md", "Running bash", "Running working_git" (`labels.toolActivity`). */
export function liveLabel(call: ToolCall, labels: Pick<ChatLabels, 'toolActivity'> = defaultChatLabels): string {
  return labels.toolActivity(call.name, preview(call.arguments));
}

/**
 * One tool call: name, status, collapsible arguments and result. Failed calls open by default.
 * `compact` renders it as a row of an activity block (no card border); `details: false` (expert mode, successful call) has nothing to expand.
 */
export function ToolCard({ entry, onOpenImage, compact = false, details = true }: { readonly entry: ToolEntry; readonly compact?: boolean; readonly details?: boolean; readonly onOpenImage?: (image: Extract<ToolResultMessage['content'][number], { type: 'image' }>) => void }) {
  const { labels } = useChatText();
  const { call, result, status } = entry;
  const [chosen, setChosen] = useState<boolean | undefined>();
  const open = details && (chosen ?? status === 'failed');
  const setOpen = (update: (value: boolean) => boolean) => setChosen(update(open));
  const hint = preview(call.arguments);
  return <div data-testid="tool-card" data-boring="tool-card" data-status={status} data-tool={call.name} data-call-id={call.id}
    className={cn('overflow-hidden', compact ? 'rounded-md' : 'rounded-lg border bg-card text-card-foreground', !compact && (status === 'failed' ? 'border-destructive/40' : 'border-border'))}>
    <button type="button" aria-expanded={details ? open : undefined} disabled={!details} onClick={() => setOpen(value => !value)}
      className={cn('flex w-full items-center gap-2 text-left outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-inset motion-reduce:transition-none',
        compact ? 'min-h-7 px-2 py-1 pointer-coarse:min-h-10' : 'min-h-9 px-3 py-1.5 pointer-coarse:min-h-10', details ? 'cursor-pointer hover:bg-muted/50' : 'cursor-default')}>
      <WrenchIcon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
      <span data-testid="tool-name" className="shrink-0 font-mono text-sm font-medium">{call.name}</span>
      {hint && <span className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground">{hint}</span>}
      {!hint && <span className="flex-1" />}
      <span data-testid="tool-status" className={cn('inline-flex shrink-0 items-center gap-1 rounded-full bg-muted px-2 py-0.5 text-xs font-medium', status === 'failed' ? 'text-destructive' : 'text-muted-foreground')}>
        <StatusIcon status={status} className="size-3" />{labels[STATUS_LABEL[status]]}</span>
      {details && <ChevronDownIcon aria-hidden="true" className={cn('size-4 shrink-0 text-muted-foreground transition-transform motion-reduce:transition-none', open && 'rotate-180')} />}
    </button>
    {details && <div hidden={!open} data-testid="tool-details" className="space-y-3 border-t border-border bg-muted/20 p-3">
      <Section title={labels.arguments}><pre className="m-0 max-h-60 overflow-auto rounded-md bg-muted/60 p-2.5 font-mono text-xs leading-5 whitespace-pre-wrap [overflow-wrap:anywhere]">{JSON.stringify(call.arguments, null, 2)}</pre></Section>
      {result && <Section title={result.isError ? labels.error : labels.result}>
        <div role={result.isError ? 'alert' : undefined} className={cn('space-y-2 rounded-md p-2.5', result.isError ? 'bg-destructive/10 text-destructive' : 'bg-muted/60')}>
          {result.content.map((part, index) => part.type === 'text'
            ? <pre key={index} className="m-0 max-h-72 overflow-auto font-mono text-xs leading-5 whitespace-pre-wrap [overflow-wrap:anywhere]">{part.text}</pre>
            : <button key={index} type="button" disabled={!onOpenImage} onClick={() => onOpenImage?.(part)} className="cursor-pointer rounded-md border border-border bg-background px-2 py-1 text-xs disabled:cursor-default">{labels.openImageResult}</button>)}
          {result.content.length === 0 && <span className="text-xs text-muted-foreground">{labels.emptyResult}</span>}
        </div></Section>}
    </div>}
  </div>;
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import { createNativeChatController } from '@hachej/boring-ui-kit/native-chat';
import type { ChatIdentity, NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { createRemoteChat } from '@hachej/boring-ui-kit/remote-chat';
import type { RemoteChat } from '@hachej/boring-ui-kit/remote-chat';
import type { PiChatActions } from './session';

// ---- Placement: where the chat is shown, reported by the component that shows it and sent with each submit (see `useRemoteChat`).
// `PiChat` reports `docked`, `AmbientChat` (also a docked chat floated by its divider) reports `floating`. Advisory for the model, never
// authority. See docs/architecture/PAGE-TOOLS.md (PLACE-1..3; draft PR #1698).
export type ChatPlacement = 'docked' | 'floating';

// Keyed by controller: a page can hold several chats, and floating or docking keeps the controller (PLACE-3).
const placements = new WeakMap<NativeChatController, ChatPlacement>();

/** Reports the placement of the chat showing `controller` while the caller is mounted. */
export function useChatPlacement(controller: NativeChatController, placement: ChatPlacement): void {
  useLayoutEffect(() => {
    placements.set(controller, placement);
    return () => { if (placements.get(controller) === placement) placements.delete(controller); };
  }, [controller, placement]);
}

export function readChatPlacement(controller: NativeChatController | undefined): ChatPlacement | undefined {
  return controller ? placements.get(controller) : undefined;
}

export type RemoteChatState =
  | { readonly status: 'connecting'; readonly conversationId: string | undefined }
  | { readonly status: 'offline'; readonly conversationId: string | undefined; readonly error: string }
  | { readonly status: 'ready'; readonly conversationId: string; readonly controller: NativeChatController; readonly actions: PiChatActions; readonly configure: RemoteChat['configure'] };

/**
 * One native chat controller per selected conversation over the host's chat transport (`createChatTransportHandler` of
 * `@hachej/boring-agent/chat-transport`). `endpoint(id)` names the transport URL of a conversation; `fetch` is the host's authenticated fetch.
 * The remote chat reopens a dropped stream itself (the controller reads `reconnecting` meanwhile); it never means the task stopped.
 * A failed connect retries every second. The previous conversation's controller is never handed out: it is disposed on change.
 */
export function useRemoteChat({ conversationId, endpoint, fetch, identity, requestContext }: {
  readonly conversationId: string | undefined;
  readonly endpoint: (conversationId: string) => string | URL;
  readonly fetch: (request: Request) => Promise<Response>;
  readonly identity: ChatIdentity | undefined;
  /**
   * The current screen context, read at each submit (for example `readAgentContext` of the app-shell item). The submit's `context` is
   * `{ placement, screen }`: the chat's placement (`docked` or `floating`, reported by `PiChat` / `AmbientChat`) and this value.
   */
  readonly requestContext?: () => Readonly<Record<string, unknown>> | undefined;
}): RemoteChatState {
  const url = conversationId === undefined ? undefined : String(endpoint(conversationId));
  const key = JSON.stringify([conversationId, url, identity?.runtimeId, identity?.scopeId, identity?.principalId]);
  const binding = useMemo(() => ({ key, fetch, requestContext }), [key]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { binding.fetch = fetch; binding.requestContext = requestContext; }, [binding, fetch, requestContext]);
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly chat: RemoteChatState }>();
  useEffect(() => {
    if (conversationId === undefined || !identity || url === undefined) return;
    const setChat = (chat: RemoteChatState) => setStored({ binding, chat });
    let disposed = false, controller: NativeChatController | undefined, remote: RemoteChat | undefined;
    const context = () => {
      const placement = readChatPlacement(controller), screen = binding.requestContext?.();
      return placement || screen ? { ...(placement && { placement }), ...(screen && { screen }) } : undefined;
    };
    setChat({ status: 'connecting', conversationId });
    void (async () => {
      while (!disposed) {
        try {
          remote = await createRemoteChat({ endpoint: url, fetch: request => binding.fetch(request), requestContext: context });
          if (disposed) return void remote.close();
          controller = createNativeChatController({ identity, ...remote });
          await controller.connect();
          if (disposed) return void controller.dispose();
          // Human-in-the-loop answers and queue withdrawal are optional on the transport: pass only what it offers.
          const actions: { answer?: RemoteChat['answer']; withdraw?: RemoteChat['withdraw'] } = {};
          if (typeof remote.answer === 'function') actions.answer = remote.answer;
          if (typeof remote.withdraw === 'function') actions.withdraw = remote.withdraw;
          setChat({ status: 'ready', controller, conversationId, actions, configure: remote.configure });
          return;
        } catch (error) {
          controller?.dispose(); controller = undefined; void remote?.close(); remote = undefined;
          if (disposed) return;
          setChat({ status: 'offline', conversationId, error: String((error as Error)?.message ?? error) });
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }
    })();
    return () => { disposed = true; controller?.dispose(); void remote?.close(); };
  }, [binding]); // eslint-disable-line react-hooks/exhaustive-deps
  return identity && stored?.binding === binding ? stored.chat : { status: 'connecting', conversationId };
}

'use client';

import { useEffect, useRef } from 'react';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';

const PREFIX = 'pi-chat:draft:';

/** The stored draft: a string, `null` when the key is missing, `undefined` when storage is unavailable (missing, blocked or throwing). */
function read(storageKey: string): string | null | undefined {
  try {
    const storage = globalThis.localStorage;
    return storage ? storage.getItem(storageKey) : undefined;
  } catch { return undefined; }
}
function write(storageKey: string, text: string): void {
  try { if (text) globalThis.localStorage?.setItem(storageKey, text); else globalThis.localStorage?.removeItem(storageKey); } catch { /* the composer still holds the text */ }
}

/**
 * Keeps the composer's half-typed message (the controller's draft) per conversation in localStorage, so it survives a reload and shows in
 * every tab on the same conversation (the `storage` event). The draft is emptied when a message is sent, and a refused send puts the text back,
 * which is written again. Without `key` nothing happens. Storage that is missing or throws only means the draft is not kept.
 *
 * On mount the conversation's saved draft replaces the composer's text; text already in the composer and not yet saved is written at once.
 * On a change of `key` (same controller) the composer shows the new conversation's saved draft, or an empty one, so no text moves across.
 */
export function useChatDraft(controller: NativeChatController, key: string | undefined): void {
  // The key the hook last loaded; a different key on a later run is a conversation switch, not a first mount.
  const loaded = useRef<string | undefined>(undefined);
  useEffect(() => {
    if (key === undefined || controller.getSnapshot().disposed) return;
    const storageKey = PREFIX + key;
    const switched = loaded.current !== undefined && loaded.current !== key;
    loaded.current = key;
    const stored = read(storageKey);
    const current = controller.getSnapshot().draft.text;
    // The text last known to be in storage; a write happens only when the composer's text differs from it.
    let saved: string;
    if (stored) {
      if (stored !== current) controller.setText(stored);
      saved = stored;
    } else if (switched) {
      // The new conversation has no saved draft (or storage is unavailable): the old conversation's text must not stay.
      if (current) controller.setText('');
      saved = '';
    } else {
      saved = current;
      if (stored === null && current) write(storageKey, current);
    }
    const persist = () => {
      if (controller.getSnapshot().disposed) return;
      const text = controller.getSnapshot().draft.text;
      if (text === saved) return;
      saved = text;
      write(storageKey, text);
    };
    const unsubscribe = controller.subscribe(persist);
    // Another tab changed this conversation's draft (or cleared all storage: `key` is null). Adopting it does not write it back.
    // Unavailable storage is not a missing draft: the composer keeps its text.
    const onStorage = (event: StorageEvent) => {
      if (event.key !== null && event.key !== storageKey) return;
      if (controller.getSnapshot().disposed) return;
      const next = read(storageKey);
      if (next === undefined) return;
      const text = next ?? '';
      saved = text;
      if (text !== controller.getSnapshot().draft.text) controller.setText(text);
    };
    globalThis.addEventListener?.('storage', onStorage);
    return () => {
      unsubscribe();
      globalThis.removeEventListener?.('storage', onStorage);
    };
  }, [controller, key]);
}

/* The languages the chat ships with. `locale` picks the base words; a host's `labels` still override any of them. */
import { defaultChatIcons, defaultChatText } from './labels';
import type { ChatText } from './labels';
import { frenchChatLabels } from './labels-fr';

export type ChatLocale = 'en' | 'fr';
const TEXT: Readonly<Record<ChatLocale, ChatText>> = { en: defaultChatText, fr: { labels: frenchChatLabels, icons: defaultChatIcons } };
/** The chat's base labels and icons for `locale` (English by default). */
export const chatTextFor = (locale: ChatLocale | undefined): ChatText => TEXT[locale ?? 'en'];
